$UrlAtajoQR = "https://www.icloud.com/shortcuts/75ccc6f6a28240fdacc029cb1303cbcd" # <-- Cambia el link ac 

function Set-QrCodeFromUrl ($url, $brush) {
    try {
        $apiUrl = "https://api.qrserver.com/v1/create-qr-code/?size=300x300&margin=3&data=" + [uri]::EscapeDataString($url)
        $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
        $bmp.BeginInit()
        $bmp.UriSource = New-Object System.Uri($apiUrl)
        # Al no usar 'CacheOption = OnLoad', WPF descarga la imagen en 2do plano sin congelar la app
        $bmp.EndInit()
        $brush.ImageSource = $bmp
    } catch { }
}

# ==========================================================
# FUNCI N MAESTRA PARA ESPERAS SIN CRASHEOS (EL SANTO GRIAL)
# ==========================================================
function Wait-Wpf {
    param([int]$Milliseconds)
    $frame = New-Object System.Windows.Threading.DispatcherFrame
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds($Milliseconds)
    $tick = {
        $timer.Stop()
        $frame.Continue = $false
    }.GetNewClosure()
    $timer.Add_Tick($tick)
    $timer.Start()
    [System.Windows.Threading.Dispatcher]::PushFrame($frame)
}

