# ==========================================================
# CLASE WIN32 EN MEMORIA RAM PURA (0ms, SIN ARCHIVOS .DLL)
# ==========================================================
# Eliminamos el .dll viejo si qued  de una prueba anterior para que Windows no lo analice
if (Test-Path "$appDataFolder\AirDropNativeV2.dll") {
    Remove-Item "$appDataFolder\AirDropNativeV2.dll" -Force -ErrorAction SilentlyContinue
}

if (-not ("Win32" -as [type])) {
    try {
        $dynAsm = [AppDomain]::CurrentDomain.DefineDynamicAssembly((New-Object System.Reflection.AssemblyName("AirDropWin32Ram")), [System.Reflection.Emit.AssemblyBuilderAccess]::Run)
        $dynMod = $dynAsm.DefineDynamicModule("AirDropWin32Mod")
        $typeBuilder = $dynMod.DefineType("Win32", [System.Reflection.TypeAttributes]"Public,Class")

        $m1 = $typeBuilder.DefinePInvokeMethod("SetCurrentProcessExplicitAppUserModelID", "shell32.dll", [System.Reflection.MethodAttributes]"Public,Static,PinvokeImpl", [System.Reflection.CallingConventions]::Standard, [void], @([string]), [System.Runtime.InteropServices.CallingConvention]::Winapi, [System.Runtime.InteropServices.CharSet]::Unicode)
        $m1.SetImplementationFlags([System.Reflection.MethodImplAttributes]::PreserveSig)

        $m2 = $typeBuilder.DefinePInvokeMethod("DwmSetWindowAttribute", "dwmapi.dll", [System.Reflection.MethodAttributes]"Public,Static,PinvokeImpl", [System.Reflection.CallingConventions]::Standard, [int], @([IntPtr], [int], [int].MakeByRefType(), [int]), [System.Runtime.InteropServices.CallingConvention]::Winapi, [System.Runtime.InteropServices.CharSet]::Ansi)
        $m2.SetImplementationFlags([System.Reflection.MethodImplAttributes]::PreserveSig)

        $m3 = $typeBuilder.DefinePInvokeMethod("LoadCursorFromFile", "user32.dll", [System.Reflection.MethodAttributes]"Public,Static,PinvokeImpl", [System.Reflection.CallingConventions]::Standard, [IntPtr], @([string]), [System.Runtime.InteropServices.CallingConvention]::Winapi, [System.Runtime.InteropServices.CharSet]::Auto)
        $m3.SetImplementationFlags([System.Reflection.MethodImplAttributes]::PreserveSig)

        $m4 = $typeBuilder.DefinePInvokeMethod("SetSystemCursor", "user32.dll", [System.Reflection.MethodAttributes]"Public,Static,PinvokeImpl", [System.Reflection.CallingConventions]::Standard, [bool], @([IntPtr], [uint32]), [System.Runtime.InteropServices.CallingConvention]::Winapi, [System.Runtime.InteropServices.CharSet]::Ansi)
        $m4.SetImplementationFlags([System.Reflection.MethodImplAttributes]::PreserveSig)

        $m5 = $typeBuilder.DefinePInvokeMethod("SystemParametersInfo", "user32.dll", [System.Reflection.MethodAttributes]"Public,Static,PinvokeImpl", [System.Reflection.CallingConventions]::Standard, [bool], @([uint32], [uint32], [IntPtr], [uint32]), [System.Runtime.InteropServices.CallingConvention]::Winapi, [System.Runtime.InteropServices.CharSet]::Ansi)
        $m5.SetImplementationFlags([System.Reflection.MethodImplAttributes]::PreserveSig)

        $m6 = $typeBuilder.DefinePInvokeMethod("SetForegroundWindow", "user32.dll", [System.Reflection.MethodAttributes]"Public,Static,PinvokeImpl", [System.Reflection.CallingConventions]::Standard, [bool], @([IntPtr]), [System.Runtime.InteropServices.CallingConvention]::Winapi, [System.Runtime.InteropServices.CharSet]::Ansi)
        $m6.SetImplementationFlags([System.Reflection.MethodImplAttributes]::PreserveSig)

        [void]$typeBuilder.CreateType()
    } catch {}
}

try { [Win32]::SetCurrentProcessExplicitAppUserModelID("AirDrop.App") } catch { }


