if ($MonitorBackground) {
    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    if (-not ("ModernMenuRenderer" -as [type])) {
        $csharpMenu = @"
using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;

public class ModernMenuRenderer : ToolStripProfessionalRenderer {
    public ModernMenuRenderer() { this.RoundedEdges = false; }
    protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e) {
        e.Graphics.Clear(Color.FromArgb(245, 245, 247));
        using (Pen pen = new Pen(Color.FromArgb(28, 0, 0, 0))) {
            int y = e.ToolStrip.Height / 2;
            e.Graphics.DrawLine(pen, 12, y, e.ToolStrip.Width - 13, y);
        }
    }
    protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e) {
    }
    protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e) {
        if (e.Item.Selected) {
            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
            e.Graphics.PixelOffsetMode = PixelOffsetMode.HighQuality;
            RectangleF rect = new RectangleF(3f, 1f, e.Item.Width - 6f, e.Item.Height - 2f);
            using (GraphicsPath path = GetRoundedRect(rect, 5f)) {
                using (SolidBrush brush = new SolidBrush(Color.FromArgb(10, 122, 255))) {
                    e.Graphics.FillPath(brush, path);
                }
            }
        }
    }
    protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e) {
        Rectangle textRect = new Rectangle(0, 0, e.Item.Width, e.Item.Height);
        Color textColor = !e.Item.Enabled ? Color.Gray : (e.Item.Selected ? Color.White : Color.FromArgb(29, 29, 31));
        TextRenderer.DrawText(e.Graphics, e.Text.Trim(), e.Item.Font, textRect, textColor, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding);
    }
    private GraphicsPath GetRoundedRect(RectangleF bounds, float radius) {
        GraphicsPath path = new GraphicsPath();
        if (radius <= 0f) { path.AddRectangle(bounds); return path; }
        float diameter = radius * 2f;
        RectangleF arc = new RectangleF(bounds.Location, new SizeF(diameter, diameter));
        path.AddArc(arc, 180f, 90f);
        arc.X = bounds.Right - diameter;
        path.AddArc(arc, 270f, 90f);
        arc.Y = bounds.Bottom - diameter;
        path.AddArc(arc, 0f, 90f);
        arc.X = bounds.Left;
        path.AddArc(arc, 90f, 90f);
        path.CloseFigure();
        return path;
    }
}
"@
        try { Add-Type -TypeDefinition $csharpMenu -ReferencedAssemblies System.Windows.Forms.dll, System.Drawing.dll -ErrorAction SilentlyContinue } catch {}
    }

    $ProcesosViejos = Get-CimInstance Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" | Where-Object { $_.CommandLine -match "-MonitorBackground" -and $_.ProcessId -ne $PID }
    if ($ProcesosViejos) { $ProcesosViejos | ForEach-Object { Stop-Process $_.ProcessId -Force -ErrorAction SilentlyContinue } }
    
    if (Test-Path $jsonPath) {
        $config = Get-Content $jsonPath -Raw | ConvertFrom-Json
        if (-not [string]::IsNullOrWhiteSpace($config.Carpeta)) {
            $global:RutaCarpeta = $config.Carpeta
            $global:AppID = "AirDrop.App"
            $global:RutaSonido = $audioDest
            $global:Cooldown = 5

            [void][Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime]
            [void][Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom.XmlDocument, ContentType = WindowsRuntime]

            $global:UltimaNotificacion = [datetime]::MinValue 
            $global:Notifier = [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier($global:AppID)
            $global:ShellApp = New-Object -ComObject Shell.Application

            $global:ToastXml = New-Object Windows.Data.Xml.Dom.XmlDocument
            $global:ToastXml.LoadXml("<toast><visual><binding template='ToastGeneric'><text>Se recibieron archivos</text></binding></visual><audio silent='true'/></toast>")

            if (-not (Test-Path $global:RutaCarpeta)) { New-Item -ItemType Directory -Path $global:RutaCarpeta | Out-Null }
            
            $hiddenForm = New-Object System.Windows.Forms.Form
            $hiddenForm.ShowInTaskbar = $false
            $hiddenForm.FormBorderStyle = 'FixedToolWindow'
            $hiddenForm.Opacity = 0

            $global:Watcher = New-Object System.IO.FileSystemWatcher -ArgumentList $global:RutaCarpeta
            $global:Watcher.EnableRaisingEvents = $true
            $global:Watcher.SynchronizingObject = $hiddenForm
            
            $global:Watcher.add_Created({
                try {
                    $Ahora = Get-Date
                    $Diferencia = ($Ahora - $global:UltimaNotificacion).TotalSeconds

                    if ($Diferencia -ge $global:Cooldown) {
                        $CarpetaAbierta = $false
                        try {
                            $CarpetaAbierta = [bool]($global:ShellApp.Windows() | Where-Object { 
                                try { $_.Document.Folder.Self.Path -eq $global:RutaCarpeta } catch { $false }
                            })
                        } catch { $CarpetaAbierta = $false }

                        if (-not $CarpetaAbierta) {
                            $global:UltimaNotificacion = $Ahora 
                            if (Test-Path $global:RutaSonido) { 
                                try {
                                    $player = New-Object System.Media.SoundPlayer($global:RutaSonido)
                                    $player.Play() 
                                } catch {}
                            }
                            try { $global:Notifier.Show($global:ToastXml) } catch {}
                            Start-Process "explorer.exe" $global:RutaCarpeta
                        }
                    }
                } catch {}
            })

            $menu = New-Object System.Windows.Forms.ContextMenuStrip
            $menu.ShowImageMargin = $false
            $menu.ShowCheckMargin = $false
            $menu.AutoSize = $true
            $menu.Renderer = [ModernMenuRenderer]::new()
            $menu.Padding = New-Object System.Windows.Forms.Padding(2, 4, 2, 4)
            $menu.Font = New-Object System.Drawing.Font("Segoe UI", 9.5)
            
            $itemAbrir = $menu.Items.Add("Abrir AirDrop")
            $itemAbrir.Margin = New-Object System.Windows.Forms.Padding(0, 0, 0, 3)
            $itemAbrir.Padding = New-Object System.Windows.Forms.Padding(0, 4, 0, 4)
            $itemAbrir.Add_Click({ Start-Process wscript.exe -ArgumentList "`"$vbsGuiPath`"" })

            $itemSalir = $menu.Items.Add("Salir")
            $itemSalir.Margin = New-Object System.Windows.Forms.Padding(0, 3, 0, 0)
            $itemSalir.Padding = New-Object System.Windows.Forms.Padding(0, 4, 0, 4)
            $itemSalir.Add_Click({
                $GuiProcs = Get-CimInstance Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" | Where-Object { $_.CommandLine -match 'AirDrop.ps1' -and $_.CommandLine -notmatch '-MonitorBackground' -and $_.ProcessId -ne $PID }
                if ($GuiProcs) { $GuiProcs | ForEach-Object { Stop-Process $_.ProcessId -Force -ErrorAction SilentlyContinue } }
                $global:NotifyIcon.Visible = $false; $global:NotifyIcon.Dispose(); $hiddenForm.Close(); [System.Windows.Forms.Application]::Exit()
            })

            $menu.add_Opened({ try { $attrValue = 2; [Win32]::DwmSetWindowAttribute($menu.Handle, 33, [ref]$attrValue, 4) | Out-Null } catch {} })

            $global:NotifyIcon = New-Object System.Windows.Forms.NotifyIcon
            if (Test-Path $icoDest) { $global:NotifyIcon.Icon = New-Object System.Drawing.Icon($icoDest) } else { $global:NotifyIcon.Icon = [System.Drawing.SystemIcons]::Information }
            $global:NotifyIcon.Text = "AirDrop"; $global:NotifyIcon.ContextMenuStrip = $menu; $global:NotifyIcon.Visible = $true
            $global:NotifyIcon.Add_DoubleClick({ Start-Process wscript.exe -ArgumentList "`"$vbsGuiPath`"" })

            [System.Windows.Forms.Application]::Run($hiddenForm)
        }
    }
    exit 
}

