            <DoubleAnimation Storyboard.TargetName="Fo_EspacioVacio1" Storyboard.TargetProperty="Opacity" To="1" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>
            <DoubleAnimation Storyboard.TargetName="Fo_EspacioVacio2" Storyboard.TargetProperty="Opacity" To="1" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>

            <DoubleAnimation Storyboard.TargetName="Fo_BtnNuevoEnviarPC" Storyboard.TargetProperty="Opacity" To="0" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>
            <DoubleAnimation Storyboard.TargetName="Fo_BadgeNuevoBoton" Storyboard.TargetProperty="Opacity" To="0" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>
            <DoubleAnimation Storyboard.TargetName="Fo_NotificacioniOS2" Storyboard.TargetProperty="Opacity" To="0" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>
            <DoubleAnimation Storyboard.TargetName="Fo_Notificacion2Translate" Storyboard.TargetProperty="Y" To="-150" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>
            <DoubleAnimation Storyboard.TargetName="Fo_AppBlur" Storyboard.TargetProperty="Radius" To="0" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>
            
            <DoubleAnimation Storyboard.TargetName="Fo_ShareSheetTranslate" Storyboard.TargetProperty="Y" To="800" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>
            <DoubleAnimation Storyboard.TargetName="Fo_EditarAccionesTranslate" Storyboard.TargetProperty="Y" To="800" BeginTime="$t_ResetCoordenadas" Duration="0:0:0.0"/>
        </Storyboard>

<!-- BOTÓN LOGO -->
        <Style TargetType="Button" x:Key="BotonLogo">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Cursor" Value="Hand"/> 
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border Background="Transparent" RenderTransformOrigin="0.5,0.5">
                            <Border.RenderTransform><ScaleTransform x:Name="Scale" ScaleX="1" ScaleY="1"/></Border.RenderTransform>
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsPressed" Value="True">
                                <Trigger.EnterActions>
                                    <BeginStoryboard><Storyboard>
                                        <DoubleAnimation Storyboard.TargetName="Scale" Storyboard.TargetProperty="ScaleX" To="0.95" Duration="0:0:0.08"/>
                                        <DoubleAnimation Storyboard.TargetName="Scale" Storyboard.TargetProperty="ScaleY" To="0.95" Duration="0:0:0.08"/>
                                    </Storyboard></BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard><Storyboard>
                                        <DoubleAnimation Storyboard.TargetName="Scale" Storyboard.TargetProperty="ScaleX" To="1" Duration="0:0:0.12"/>
                                        <DoubleAnimation Storyboard.TargetName="Scale" Storyboard.TargetProperty="ScaleY" To="1" Duration="0:0:0.12"/>
                                    </Storyboard></BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

<!-- BOTÓN PRIMARIO MACOS SEQUOIA (Azul Apple #007AFF con ClearType fijo) -->
        <Style TargetType="Button" x:Key="BotonMacPrimario">
            <Setter Property="TextOptions.TextHintingMode" Value="Fixed"/>
            <Setter Property="Background">
                <Setter.Value>
                    <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                        <GradientStop Color="#FF1E8FFF" Offset="0.0"/>
                        <GradientStop Color="#FF007AFF" Offset="1.0"/>
                    </LinearGradientBrush>
                </Setter.Value>
            </Setter>
            <Setter Property="Foreground" Value="#FFFFFF"/>
            <Setter Property="BorderBrush" Value="#26000000"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="FontFamily" Value="Segoe UI Variable Text, Segoe UI"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="Medium"/>
            <Setter Property="Padding" Value="14,5"/>
            <Setter Property="Margin" Value="5,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Grid>
                            <Border CornerRadius="6" Background="#01000000">
                                <Border.Effect>
                                    <DropShadowEffect Color="#004099" BlurRadius="4" ShadowDepth="1" Opacity="0.22" Direction="270"/>
                                </Border.Effect>
                            </Border>
                            <Border x:Name="BtnBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="6" RenderOptions.ClearTypeHint="Enabled">
                                <Grid>
                                    <Border CornerRadius="5" BorderBrush="#38FFFFFF" BorderThickness="0,1,0,0"/>
                                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}"/>
                                </Grid>
                            </Border>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="BtnBorder" Property="Background" Value="#0062CC"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- BOTÓN SECUNDARIO MACOS SEQUOIA (Blanco elevado con ClearType fijo) -->
        <Style TargetType="Button" x:Key="BotonMacSecundario">
            <Setter Property="TextOptions.TextHintingMode" Value="Fixed"/>
            <Setter Property="Background" Value="#FFFFFF"/>
            <Setter Property="Foreground" Value="#1D1D1F"/>
            <Setter Property="BorderBrush" Value="#24000000"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="FontFamily" Value="Segoe UI Variable Text, Segoe UI"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="Normal"/>
            <Setter Property="Padding" Value="14,5"/>
            <Setter Property="Margin" Value="5,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Grid>
                            <Border CornerRadius="6" Background="#01000000">
                                <Border.Effect>
                                    <DropShadowEffect Color="Black" BlurRadius="3" ShadowDepth="1" Opacity="0.08" Direction="270"/>
                                </Border.Effect>
                            </Border>
                            <Border x:Name="BtnBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="6" RenderOptions.ClearTypeHint="Enabled">
                                <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}"/>
                            </Border>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="BtnBorder" Property="Background" Value="#F9F9FB"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="BtnBorder" Property="Background" Value="#EAEAEF"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- BOTÓN DESTRUCTIVO SÓLIDO (Con ClearType fijo) -->
        <Style TargetType="Button" x:Key="BotonMacPeligro">
            <Setter Property="TextOptions.TextHintingMode" Value="Fixed"/>
            <Setter Property="Background">
                <Setter.Value>
                    <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
                        <GradientStop Color="#FFFF5147" Offset="0.0"/>
                        <GradientStop Color="#FFFF3B30" Offset="1.0"/>
                    </LinearGradientBrush>
                </Setter.Value>
            </Setter>
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="BorderBrush" Value="#26000000"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="FontFamily" Value="Segoe UI Variable Text, Segoe UI"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="Medium"/>
            <Setter Property="Padding" Value="14,5"/>
            <Setter Property="Margin" Value="5,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Grid>
                            <Border CornerRadius="6" Background="#01000000">
                                <Border.Effect>
                                    <DropShadowEffect Color="#99150D" BlurRadius="4" ShadowDepth="1" Opacity="0.22" Direction="270"/>
                                </Border.Effect>
                            </Border>
                            <Border x:Name="BtnBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="6" RenderOptions.ClearTypeHint="Enabled">
                                <Grid>
                                    <Border CornerRadius="5" BorderBrush="#35FFFFFF" BorderThickness="0,1,0,0"/>
                                    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" Margin="{TemplateBinding Padding}"/>
                                </Grid>
                            </Border>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="BtnBorder" Property="Background" Value="#D7281E"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- SWITCH MACOS (Relleno 100% sólido sin filtración de bordes y a 144 FPS) -->
        <Style TargetType="CheckBox" x:Key="MacCheckbox">
            <Setter Property="Foreground" Value="#1D1D1F"/>
            <Setter Property="FontFamily" Value="Segoe UI Variable Text, Segoe UI"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="HorizontalAlignment" Value="Stretch"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="CheckBox">
                        <Grid Background="Transparent" VerticalAlignment="Center">
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="*"/>
                                <ColumnDefinition Width="Auto"/>
                            </Grid.ColumnDefinitions>
                            <ContentPresenter Grid.Column="0" VerticalAlignment="Center" Margin="0,0,10,0"/>
                            <Grid Grid.Column="1" Width="34" Height="20" VerticalAlignment="Center" SnapsToDevicePixels="False" UseLayoutRounding="False">
                                <Border x:Name="SwitchTrack" CornerRadius="10" Background="#D2D2D7" BorderThickness="0"/>
                                <Border x:Name="SwitchKnob" Width="16" Height="16" CornerRadius="8" Background="#FFFFFF" BorderBrush="#18000000" BorderThickness="0.8" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="2,0,0,0" RenderTransformOrigin="0.5,0.5">
                                    <Border.RenderTransform>
                                        <TranslateTransform x:Name="KnobTranslate" X="0"/>
                                    </Border.RenderTransform>
                                </Border>
                            </Grid>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="SwitchTrack" Property="Background" Value="#007AFF"/>
                                <Setter TargetName="SwitchKnob" Property="BorderBrush" Value="#00000000"/>
                                <Trigger.EnterActions>
                                    <BeginStoryboard><Storyboard Timeline.DesiredFrameRate="144">
                                        <DoubleAnimation Storyboard.TargetName="KnobTranslate" Storyboard.TargetProperty="X" To="14" Duration="0:0:0.15">
                                            <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                                        </DoubleAnimation>
                                    </Storyboard></BeginStoryboard>
                                </Trigger.EnterActions>
                                <Trigger.ExitActions>
                                    <BeginStoryboard><Storyboard Timeline.DesiredFrameRate="144">
                                        <DoubleAnimation Storyboard.TargetName="KnobTranslate" Storyboard.TargetProperty="X" To="0" Duration="0:0:0.15">
                                            <DoubleAnimation.EasingFunction><CubicEase EasingMode="EaseOut"/></DoubleAnimation.EasingFunction>
                                        </DoubleAnimation>
                                    </Storyboard></BeginStoryboard>
                                </Trigger.ExitActions>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- CAJA DE TEXTO CON ANILLO DE ENFOQUE (FOCUS RING) NATIVO DE MACOS -->
        <Style TargetType="Border" x:Key="MacInputBorder">
            <Setter Property="CornerRadius" Value="6"/>
            <Setter Property="Background" Value="#FFFFFF"/>
            <Setter Property="BorderBrush" Value="#D2D2D7"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Style.Triggers>
                <Trigger Property="IsKeyboardFocusWithin" Value="True">
                    <Setter Property="BorderBrush" Value="#007AFF"/>
                    <Setter Property="Effect">
                        <Setter.Value>
                            <DropShadowEffect Color="#007AFF" BlurRadius="7" ShadowDepth="0" Opacity="0.35"/>
                        </Setter.Value>
                    </Setter>
                </Trigger>
            </Style.Triggers>
        </Style>
    </Window.Resources>

    <Window.Triggers>
        <EventTrigger RoutedEvent="Window.Loaded">
            <BeginStoryboard x:Name="AnimacionAbrir" Storyboard="{StaticResource AnimacionAbrir}"/>
        </EventTrigger>
    </Window.Triggers>

    <!-- CONTENEDOR PRINCIPAL -->
    <Grid x:Name="BordePrincipal" Opacity="0" Margin="26,20,26,32" RenderTransformOrigin="0.5,0.5" Width="550" VerticalAlignment="Top">
        <Grid.RenderTransform>
            <TransformGroup>
                <ScaleTransform x:Name="WindowScale" ScaleX="0.88" ScaleY="0.88"/>
                <TranslateTransform x:Name="WindowTranslate" X="0" Y="0"/>
            </TransformGroup>
        </Grid.RenderTransform>

        <!-- Capa 1: Sombra ambiental macOS -->
        <Border CornerRadius="12" Background="#FFF5F5F7">
            <Border.Effect>
                <DropShadowEffect Color="Black" Direction="270" ShadowDepth="6" BlurRadius="22" Opacity="0.22"/>
            </Border.Effect>
        </Border>

        <!-- Capa 2: Ventana con Bisel Interno de Cristal -->
        <Border CornerRadius="12" Background="#FFF5F5F7" BorderBrush="#28000000" BorderThickness="1" ClipToBounds="True">
            <Border CornerRadius="11" BorderBrush="#CCFFFFFF" BorderThickness="1" ClipToBounds="True">
                <Grid>
                    <!-- SEMÁFORO MACOS (Centrado sub-píxel exacto y mismo grosor en negrita) -->
                    <StackPanel x:Name="PanelSemaforo" Orientation="Horizontal" HorizontalAlignment="Left" VerticalAlignment="Top" Margin="14,14,0,0" Panel.ZIndex="100" Background="Transparent" UseLayoutRounding="False" SnapsToDevicePixels="False">
                        <Button x:Name="BtnCerrarVentana" Width="13" Height="13" Margin="0,0,8,0" Cursor="Hand" BorderThickness="0" Background="Transparent">
                            <Button.Template>
                                <ControlTemplate TargetType="Button">
                                    <Grid Width="13" Height="13">
                                        <Border x:Name="circleRojo" CornerRadius="6.5" Background="#FF5F57" BorderBrush="#E0443E" BorderThickness="1"/>
                                        <Canvas x:Name="iconCruz" Width="13" Height="13" Visibility="Hidden" IsHitTestVisible="False">
                                            <Path Data="M 4.1,4.1 L 8.9,8.9 M 8.9,4.1 L 4.1,8.9" Stroke="#4D0000" StrokeThickness="1.85" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                        </Canvas>
                                    </Grid>
                                    <ControlTemplate.Triggers>
                                        <DataTrigger Binding="{Binding IsActive, RelativeSource={RelativeSource AncestorType=Window}}" Value="False">
                                            <Setter TargetName="circleRojo" Property="Background" Value="#DCDCE0"/>
                                            <Setter TargetName="circleRojo" Property="BorderBrush" Value="#CCCCD0"/>
                                        </DataTrigger>
                                        <DataTrigger Binding="{Binding IsMouseOver, ElementName=PanelSemaforo}" Value="True">
                                            <Setter TargetName="circleRojo" Property="Background" Value="#FF5F57"/>
                                            <Setter TargetName="circleRojo" Property="BorderBrush" Value="#E0443E"/>
                                            <Setter TargetName="iconCruz" Property="Visibility" Value="Visible"/>
                                        </DataTrigger>
                                        <Trigger Property="IsPressed" Value="True">
                                            <Setter TargetName="circleRojo" Property="Background" Value="#BF4942"/>
                                            <Setter TargetName="circleRojo" Property="BorderBrush" Value="#A63A34"/>
                                        </Trigger>
                                    </ControlTemplate.Triggers>
                                </ControlTemplate>
                            </Button.Template>
                        </Button>
                        <Button x:Name="BtnMinimizarVentana" Width="13" Height="13" Margin="0,0,8,0" Cursor="Hand" BorderThickness="0" Background="Transparent">
                            <Button.Template>
                                <ControlTemplate TargetType="Button">
                                    <Grid Width="13" Height="13">
                                        <Border x:Name="circleAmarillo" CornerRadius="6.5" Background="#FEBC2E" BorderBrush="#D89E24" BorderThickness="1"/>
                                        <Canvas x:Name="iconGuion" Width="13" Height="13" Visibility="Hidden" IsHitTestVisible="False">
                                            <Path Data="M 3.7,6.5 L 9.3,6.5" Stroke="#5C3D00" StrokeThickness="1.85" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                        </Canvas>
                                    </Grid>
                                    <ControlTemplate.Triggers>
                                        <DataTrigger Binding="{Binding IsActive, RelativeSource={RelativeSource AncestorType=Window}}" Value="False">
                                            <Setter TargetName="circleAmarillo" Property="Background" Value="#DCDCE0"/>
                                            <Setter TargetName="circleAmarillo" Property="BorderBrush" Value="#CCCCD0"/>
                                        </DataTrigger>
                                        <DataTrigger Binding="{Binding IsMouseOver, ElementName=PanelSemaforo}" Value="True">
                                            <Setter TargetName="circleAmarillo" Property="Background" Value="#FEBC2E"/>
                                            <Setter TargetName="circleAmarillo" Property="BorderBrush" Value="#D89E24"/>
                                            <Setter TargetName="iconGuion" Property="Visibility" Value="Visible"/>
                                        </DataTrigger>
                                        <Trigger Property="IsPressed" Value="True">
                                            <Setter TargetName="circleAmarillo" Property="Background" Value="#BF8E22"/>
                                            <Setter TargetName="circleAmarillo" Property="BorderBrush" Value="#A3771B"/>
                                        </Trigger>
                                    </ControlTemplate.Triggers>
                                </ControlTemplate>
                            </Button.Template>
                        </Button>
                        <Button Width="13" Height="13" IsEnabled="False" BorderThickness="0" Background="Transparent">
                            <Button.Template>
                                <ControlTemplate TargetType="Button">
                                    <Border CornerRadius="6.5" Background="#DCDCE0" BorderBrush="#CCCCD0" BorderThickness="1"/>
                                </ControlTemplate>
                            </Button.Template>
                        </Button>
                    </StackPanel>

<!-- BOTÓN DE AYUDA (?) ESTILO MACOS EN ESQUINA SUPERIOR DERECHA -->
                    <Button Background="Transparent" BorderThickness="0" Cursor="Hand" Height="22" HorizontalAlignment="Right" Margin="0,12,14,0" Panel.ZIndex="100" VerticalAlignment="Top" Width="22" x:Name="BtnAyuda">
                        <Button.Template>
                            <ControlTemplate TargetType="Button">
                                <Grid>
                                    <Border Background="#01000000" CornerRadius="11">
                                        <Border.Effect>
                                            <DropShadowEffect BlurRadius="3" Color="Black" Direction="270" Opacity="0.10" ShadowDepth="1"/>
                                        </Border.Effect>
                                    </Border>
                                    <Border Background="#FFFFFF" BorderBrush="#24000000" BorderThickness="1" CornerRadius="11" RenderOptions.ClearTypeHint="Enabled" x:Name="HelpBorder">
                                        <TextBlock FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12.5" FontWeight="SemiBold" Foreground="#6E6E73" HorizontalAlignment="Center" Margin="0,-1,0,0" Text="?" VerticalAlignment="Center"/>
                                    </Border>
                                </Grid>
                                <ControlTemplate.Triggers>
                                    <Trigger Property="IsMouseOver" Value="True">
                                        <Setter Property="Background" TargetName="HelpBorder" Value="#F5F5F7"/>
                                    </Trigger>
                                    <Trigger Property="IsPressed" Value="True">
                                        <Setter Property="Background" TargetName="HelpBorder" Value="#E5E5EA"/>
                                    </Trigger>
                                </ControlTemplate.Triggers>
                            </ControlTemplate>
                        </Button.Template>
                    </Button>

                    <!-- CUERPO CENTRAL DE LA APP CON FILA INFERIOR INTERNA ANTI-RECORTE -->
                    <Grid Margin="0,30,0,0" Width="550" HorizontalAlignment="Center" VerticalAlignment="Top">
                        <Grid.RowDefinitions>
                            <RowDefinition Height="180"/> 
                            <RowDefinition Height="15"/>   
                            <RowDefinition Height="38"/> 
                            <RowDefinition x:Name="RowEspacioTitulo" Height="30"/>   
                            <RowDefinition x:Name="RowCuerpo" Height="82"/>   
                            <RowDefinition x:Name="RowEspacioBotones" Height="30"/>   
                            <RowDefinition Height="30"/>
                            <RowDefinition x:Name="RowMargenInferior" Height="30"/> 
                        </Grid.RowDefinitions>

                        <Button x:Name="BtnLogo" Grid.Row="0" Style="{StaticResource BotonLogo}" Width="180" Height="180" HorizontalAlignment="Center" Cursor="Arrow" RenderTransformOrigin="0.5,0.5">
                            <Button.RenderTransform>
                                <TransformGroup>
                                    <ScaleTransform x:Name="LogoScale" ScaleX="1" ScaleY="1"/>
                                    <TranslateTransform x:Name="LogoTranslate" X="0" Y="0"/>
                                </TransformGroup>
                            </Button.RenderTransform>
                            <Image x:Name="LogoImage" Stretch="Uniform"/>
                        </Button>
                        
                        <TextBlock x:Name="TxtAirDropTitle" Grid.Row="2" Text="AirDrop" FontFamily="Segoe UI Variable Display, Segoe UI" FontSize="28" FontWeight="SemiBold" Foreground="#1D1D1F" HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                            <TextBlock.RenderTransform>
                                <TransformGroup>
                                    <ScaleTransform x:Name="TitleScale" ScaleX="1" ScaleY="1"/>
                                    <TranslateTransform x:Name="TitleTranslate" X="0" Y="0"/>
                                </TransformGroup>
                            </TextBlock.RenderTransform>
                        </TextBlock>
                        
                        <Grid Grid.Row="4" x:Name="ContainerBody" Margin="0,-18,0,-18">
                            <Grid x:Name="BodyInstalar" Opacity="0" Visibility="Collapsed" IsHitTestVisible="False" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                                <Grid.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </Grid.RenderTransform>
                            </Grid>

                            <Grid x:Name="BodyPrincipal" Opacity="0" Visibility="Collapsed" IsHitTestVisible="False" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                                <Grid.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </Grid.RenderTransform>
                                <Grid.RowDefinitions>
                                    <RowDefinition Height="28"/>
                                    <RowDefinition Height="18"/>
                                    <RowDefinition Height="36"/>
                                </Grid.RowDefinitions>

                                <StackPanel Grid.Row="0" Orientation="Horizontal" HorizontalAlignment="Center">
                                    <Border BorderBrush="#D2D2D7" BorderThickness="1" CornerRadius="6" Background="#FFFFFF" Width="380" Height="28">
                                        <Border.Effect>
                                            <DropShadowEffect Color="Black" BlurRadius="2" ShadowDepth="0.5" Opacity="0.04" Direction="270"/>
                                        </Border.Effect>
                                        <Grid>
                                            <TextBox x:Name="TxtRuta" Text="Seleccionar carpeta para monitorizar." IsReadOnly="True" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" Foreground="#86868B" BorderThickness="0" Background="Transparent" TextAlignment="Left" VerticalAlignment="Center" Padding="8,0"/>
                                            <TextBlock x:Name="TxtSuccess" Text="Carpeta compartida con &#x00E9;xito" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" Foreground="#86868B" VerticalAlignment="Center" Margin="10,0,0,0" Opacity="0" IsHitTestVisible="False"/>
                                        </Grid>
                                    </Border>
                                    <Button x:Name="BtnExaminar" Content="&#x22EF;" Style="{StaticResource BotonMacSecundario}" Width="36" Height="28" Padding="0,0,0,1" Margin="8,0,0,0" FontWeight="SemiBold" FontSize="14"/>
                                </StackPanel>
                                
                                <!-- Tarjeta agrupada macOS para los Switches (mismo ancho exacto de 424px que la fila superior) -->
                                <Border Grid.Row="2" Width="424" Height="36" CornerRadius="8" Background="#99FFFFFF" BorderBrush="#18000000" BorderThickness="1" HorizontalAlignment="Center" VerticalAlignment="Center">
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="1"/>
                                            <ColumnDefinition Width="*"/>
                                        </Grid.ColumnDefinitions>
                                        <CheckBox x:Name="ChkWindows" Grid.Column="0" Style="{StaticResource MacCheckbox}" Content="Iniciar con Windows" Margin="12,0,12,0"/>
                                        <Rectangle Grid.Column="1" Width="1" Fill="#14000000" Margin="0,6"/>
                                        <CheckBox x:Name="ChkCompartida" Grid.Column="2" Style="{StaticResource MacCheckbox}" Content="Carpeta compartida" Margin="12,0,12,0"/>
                                    </Grid>
                                </Border>
                            </Grid>

                            <Grid x:Name="BodyCredenciales" Opacity="0" Visibility="Collapsed" IsHitTestVisible="False" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                                <Grid.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </Grid.RenderTransform>
                                <Grid.RowDefinitions>
                                    <RowDefinition Height="28"/>
                                    <RowDefinition Height="26"/>
                                    <RowDefinition Height="28"/>
                                </Grid.RowDefinitions>

                                <Grid Grid.Row="0" Width="260" Height="28" HorizontalAlignment="Center">
                                    <Border Style="{StaticResource MacInputBorder}" Width="260" Height="28">
                                        <TextBox x:Name="TxtUsuario" Text="" CaretBrush="Transparent" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" Foreground="#1D1D1F" BorderThickness="0" Background="Transparent" TextAlignment="Left" VerticalAlignment="Center" Margin="0,-1.5,0,0" Padding="8,0"/>
                                    </Border>
                                    <TextBlock x:Name="PlaceholderUsuario" Text="Escribir usuario..." FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" Foreground="#86868B" TextAlignment="Left" VerticalAlignment="Center" Margin="0,-1.5,0,0" Padding="10,0" IsHitTestVisible="False"/>
                                </Grid>

                                <Grid Grid.Row="2" Width="260" Height="28" HorizontalAlignment="Center">
                                    <Border Style="{StaticResource MacInputBorder}" Width="260" Height="28">
                                        <TextBox x:Name="TxtPassword" Text="" CaretBrush="Transparent" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" Foreground="#1D1D1F" BorderThickness="0" Background="Transparent" TextAlignment="Left" VerticalAlignment="Center" Margin="0,-1.5,0,0" Padding="8,0"/>
                                    </Border>
                                    <TextBlock x:Name="PlaceholderPassword" Text="Escribir contrase&#x00F1;a..." FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" Foreground="#86868B" TextAlignment="Left" VerticalAlignment="Center" Margin="0,-1.5,0,0" Padding="10,0" IsHitTestVisible="False"/>
                                </Grid>
                            </Grid>

                            <Grid IsHitTestVisible="False" Opacity="0" RenderTransformOrigin="0.5,0.5" VerticalAlignment="Center" Visibility="Collapsed" x:Name="BodyDesinstalar">
                                <Grid.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </Grid.RenderTransform>
                                <Border Background="#FFF5F5F7" RenderOptions.ClearTypeHint="Enabled" HorizontalAlignment="Center">
                                    <TextBlock FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="14" Foreground="#1D1D1F" LineHeight="20" LineStackingStrategy="BlockLineHeight" Text="Se desinstalar&#x00E1; AirDrop y todos sus archivos. La carpeta dejar&#x00E1; de compartirse, pero sus datos no se modificar&#x00E1;n." TextAlignment="Center" TextWrapping="Wrap" Width="410"/>
                                </Border>
                            </Grid>

                            <Grid IsHitTestVisible="False" Opacity="0" RenderTransformOrigin="0.5,0.5" VerticalAlignment="Center" Visibility="Collapsed" x:Name="BodyConfirmarRed">
                                <Grid.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </Grid.RenderTransform>
                                <Border Background="#FFF5F5F7" RenderOptions.ClearTypeHint="Enabled" HorizontalAlignment="Center">
                                    <StackPanel VerticalAlignment="Center" Width="420">
                                        <TextBlock FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="14" Foreground="#1D1D1F" LineHeight="20" LineStackingStrategy="BlockLineHeight" Text="&#x00BF;Confi&#x00E1;s en la red conectada actualmente?" TextAlignment="Center" TextWrapping="Wrap"/>
                                        <TextBlock FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="14" Foreground="#1D1D1F" LineHeight="20" LineStackingStrategy="BlockLineHeight" Margin="0,4,0,0" Text="El perfil de red pasar&#x00E1; a ser privado. No actives esta opci&#x00F3;n en redes Wi-Fi p&#x00FA;blicas." TextAlignment="Center" TextWrapping="Wrap"/>
                                    </StackPanel>
                                </Border>
                            </Grid>
                        </Grid>

                        <Grid Grid.Row="6" Margin="0,-18,0,-18" x:Name="ContainerBotones">
                            <StackPanel HorizontalAlignment="Center" IsHitTestVisible="False" Opacity="0" Orientation="Horizontal" RenderTransformOrigin="0.5,0.5" VerticalAlignment="Center" Visibility="Collapsed" x:Name="BotonesInstalar">
                                <StackPanel.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </StackPanel.RenderTransform>
                                <Button Content="Instalar" Style="{StaticResource BotonMacPrimario}" Width="110" x:Name="BtnInstalar"/>
                            </StackPanel>

                            <StackPanel HorizontalAlignment="Center" IsHitTestVisible="False" Opacity="0" Orientation="Horizontal" RenderTransformOrigin="0.5,0.5" VerticalAlignment="Center" Visibility="Collapsed" x:Name="BotonesPrincipal">
                                <StackPanel.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </StackPanel.RenderTransform>
                                <Button Content="Vincular iPhone" Margin="0,0,7,0" Style="{StaticResource BotonMacSecundario}" Width="135" x:Name="BtnAtajo"/>
                                <Button Content="Crear credenciales" Margin="7,0,0,0" Style="{StaticResource BotonMacPrimario}" Width="140" x:Name="BtnCredenciales"/>
                            </StackPanel>

                            <StackPanel HorizontalAlignment="Center" IsHitTestVisible="False" Opacity="0" Orientation="Horizontal" RenderTransformOrigin="0.5,0.5" VerticalAlignment="Center" Visibility="Collapsed" x:Name="BotonesCredenciales">
                                <StackPanel.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </StackPanel.RenderTransform>
                                <Button Content="Eliminar credenciales" Margin="0,0,14,0" Style="{StaticResource BotonMacPeligro}" Visibility="Collapsed" Width="160" x:Name="BtnEliminarCredenciales"/>
                                <Button Content="Volver" Style="{StaticResource BotonMacSecundario}" Width="105" x:Name="BtnVolver"/>
                                <Button Content="Continuar" Margin="14,0,0,0" Style="{StaticResource BotonMacPrimario}" Width="105" x:Name="BtnContinuar"/>
                            </StackPanel>

                            <StackPanel HorizontalAlignment="Center" IsHitTestVisible="False" Opacity="0" Orientation="Horizontal" RenderTransformOrigin="0.5,0.5" VerticalAlignment="Center" Visibility="Collapsed" x:Name="BotonesDesinstalar">
                                <StackPanel.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </StackPanel.RenderTransform>
                                <Button Content="Cancelar" Margin="0,0,14,0" Style="{StaticResource BotonMacSecundario}" Width="105" x:Name="BtnCancelarDesinstalar"/>
                                <Button Content="Desinstalar" Style="{StaticResource BotonMacPeligro}" Width="105" x:Name="BtnConfirmarDesinstalar"/>
                            </StackPanel>

                            <StackPanel HorizontalAlignment="Center" IsHitTestVisible="False" Opacity="0" Orientation="Horizontal" RenderTransformOrigin="0.5,0.5" VerticalAlignment="Center" Visibility="Collapsed" x:Name="BotonesConfirmarRed">
                                <StackPanel.RenderTransform>
                                    <TransformGroup>
                                        <ScaleTransform ScaleX="1" ScaleY="1"/>
                                        <TranslateTransform X="0" Y="0"/>
                                    </TransformGroup>
                                </StackPanel.RenderTransform>
                                <Button Content="Cancelar" Margin="0,0,14,0" Style="{StaticResource BotonMacSecundario}" Width="105" x:Name="BtnCancelarRed"/>
                                <Button Content="S&#x00ED;, confiar" Style="{StaticResource BotonMacPrimario}" Width="105" x:Name="BtnConfirmarRed"/>
                            </StackPanel>
                        </Grid>

                        <!-- PANEL DE ATAJOS -->
                        <Grid x:Name="AtajosFullPanel" Grid.Row="0" Grid.RowSpan="7" Opacity="0" Visibility="Collapsed" Panel.ZIndex="500" VerticalAlignment="Stretch" RenderTransformOrigin="0.5,0.5">
                            <Grid.RenderTransform>
                                <TransformGroup>
                                    <ScaleTransform ScaleX="1" ScaleY="1"/>
                                    <TranslateTransform X="0" Y="0"/>
                                </TransformGroup>
                            </Grid.RenderTransform>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="140"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>

                            <!-- COLUMNA IZQUIERDA (POSICIONAMIENTO ABSOLUTO) -->
                            <Grid Grid.Column="0" Panel.ZIndex="9999">
                                <!-- Botón Archivos -->
                                <Button x:Name="BtnAppArchivos" Style="{StaticResource BotonLogo}" Width="60" Height="60" VerticalAlignment="Top" HorizontalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                                    <Button.RenderTransform><TranslateTransform x:Name="TransArchivos" X="0" Y="0"/></Button.RenderTransform>
                                    <Grid Width="60" Height="60">
                                        <Border Width="60" Height="60" CornerRadius="14" ClipToBounds="True">
                                            <Image x:Name="ImgAppArchivos" Stretch="UniformToFill"/>
                                        </Border>
                                        <Canvas Width="60" Height="60">
                                            <Border Canvas.Left="-20" Canvas.Top="68" Width="100" Background="#FFF5F5F7" RenderOptions.ClearTypeHint="Enabled">
                                                <TextBlock Text="Archivos" FontFamily="Segoe UI Variable Text, Segoe UI" Foreground="#1D1D1F" FontWeight="Medium" FontSize="12.5" TextAlignment="Center"/>
                                            </Border>
                                        </Canvas>
                                    </Grid>
                                </Button>
                                
                                <!-- Botón Atajos -->
                                <Button x:Name="BtnAppAtajos" Style="{StaticResource BotonLogo}" Width="60" Height="60" VerticalAlignment="Top" HorizontalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                                    <Button.RenderTransform><TranslateTransform x:Name="TransAtajos" X="0" Y="0"/></Button.RenderTransform>
                                    <Grid Width="60" Height="60">
                                        <Border Width="60" Height="60" CornerRadius="14" ClipToBounds="True">
                                            <Image x:Name="ImgAppAtajos" Stretch="UniformToFill"/>
                                        </Border>
                                        <Canvas Width="60" Height="60">
                                            <Border Canvas.Left="-20" Canvas.Top="68" Width="100" Background="#FFF5F5F7" RenderOptions.ClearTypeHint="Enabled">
                                                <TextBlock Text="Atajos" FontFamily="Segoe UI Variable Text, Segoe UI" Foreground="#1D1D1F" FontWeight="Medium" FontSize="12.5" TextAlignment="Center"/>
                                            </Border>
                                        </Canvas>
                                    </Grid>
                                </Button>
                                
                                <!-- Botón Fotos -->
                                <Button x:Name="BtnAppFotos" Style="{StaticResource BotonLogo}" Width="60" Height="60" VerticalAlignment="Top" HorizontalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                                    <Button.RenderTransform><TranslateTransform x:Name="TransFotos" X="0" Y="0"/></Button.RenderTransform>
                                    <Grid Width="60" Height="60">
                                        <Border Width="60" Height="60" CornerRadius="14" ClipToBounds="True">
                                            <Image x:Name="ImgAppFotos" Stretch="UniformToFill"/>
                                        </Border>
                                        <Canvas Width="60" Height="60">
                                            <Border Canvas.Left="-20" Canvas.Top="68" Width="100" Background="#FFF5F5F7" RenderOptions.ClearTypeHint="Enabled">
                                                <TextBlock Text="Fotos" FontFamily="Segoe UI Variable Text, Segoe UI" Foreground="#1D1D1F" FontWeight="Medium" FontSize="12.5" TextAlignment="Center"/>
                                            </Border>
                                        </Canvas>
                                    </Grid>
                                </Button>

                                <!-- Botón Volver anclado perfectamente abajo -->
                                <Button x:Name="BtnVolverAtajos" Content="Volver" Style="{StaticResource BotonMacSecundario}" Width="105" HorizontalAlignment="Center" VerticalAlignment="Top" Margin="0" Panel.ZIndex="2000"/>
                            </Grid>

                    <!-- COLUMNA DERECHA (Contenedores de Animaciones fijos y ClipToBounds aisla las animaciones) -->
                    <Grid Grid.Column="1" Background="Transparent" ClipToBounds="True">
                        
                        <!-- CONTENEDOR ARCHIVOS -->
                        <Grid x:Name="Ar_AnimacionContainer" Visibility="Hidden" HorizontalAlignment="Center" VerticalAlignment="Center" Width="289" Height="334" TextOptions.TextHintingMode="Fixed">
                            <Viewbox Stretch="Uniform" Width="289" Height="334">
                                <Grid Width="450" Height="520">
                                    <Grid x:Name="Ar_AppWindowContainer" Opacity="0" RenderTransformOrigin="0.5, 0.5">
                                        <Grid.RenderTransform><ScaleTransform x:Name="Ar_AppWindowScale" ScaleX="0.2076" ScaleY="0.1797"/></Grid.RenderTransform>
                                        <Grid Margin="25">
                                            <Border x:Name="Ar_AnimatedBackground" Background="#F2F2F7" CornerRadius="105" Opacity="1"/>
                                            <Border x:Name="Ar_RealBackground" Background="#F2F2F7" CornerRadius="40" Opacity="0">
                                                <Grid>
                                                    <Grid.Clip><RectangleGeometry Rect="0,0,400,470" RadiusX="40" RadiusY="40"/></Grid.Clip>
                                                    <Grid x:Name="Ar_ExplorarContent" Opacity="0" VerticalAlignment="Top" Margin="20">
                                                        <Grid.RowDefinitions>
                                                            <RowDefinition Height="Auto"/>
                                                            <RowDefinition Height="Auto"/>
                                                            <RowDefinition Height="Auto"/>
                                                        </Grid.RowDefinitions>
                                                        <Border Grid.Row="0" Width="36" Height="36" CornerRadius="18" Background="#FFFFFF" HorizontalAlignment="Right" Margin="0,0,0,4" RenderTransformOrigin="0.5,0.5" SnapsToDevicePixels="True" UseLayoutRounding="True">
                                                            <Grid Width="22" Height="10" HorizontalAlignment="Center" VerticalAlignment="Center" SnapsToDevicePixels="True" UseLayoutRounding="True">
                                                                <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center">
                                                                    <Ellipse Width="4" Height="4" Fill="#000000" Margin="1,0,1,0"/>
                                                                    <Ellipse Width="4" Height="4" Fill="#000000" Margin="1,0,1,0"/>
                                                                    <Ellipse Width="4" Height="4" Fill="#000000" Margin="1,0,1,0"/>
                                                                </StackPanel>
                                                            </Grid>
                                                        </Border>
                                                        <TextBlock Grid.Row="1" Text="Explorar" FontSize="34" FontWeight="Bold" Foreground="#000000" HorizontalAlignment="Left" Margin="0,0,0,16"/>
                                                        <Border Grid.Row="2" Background="#E4E4E6" CornerRadius="20" Height="40">
                                                            <StackPanel Orientation="Horizontal" VerticalAlignment="Center" Margin="12,0,0,0">
                                                                <Canvas Width="18" Height="18" Margin="0,0,8,0" VerticalAlignment="Center">
                                                                    <Path Data="M 7.5,2 A 5.5,5.5 0 1 0 7.5,13 A 5.5,5.5 0 1 0 7.5,2 Z M 11.5,11.5 L 16.5,16.5" Stroke="#000000" StrokeThickness="2.2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round"/>
                                                                </Canvas>
                                                                <TextBlock Text="Buscar" FontSize="17" Foreground="#8E8E93" VerticalAlignment="Center" Margin="0,-2,0,0"/>
                                                            </StackPanel>
                                                        </Border>
                                                    </Grid>
<!-- PÍLDORA INFERIOR DE ARCHIVOS (Sombra aislada en Capa 1 para mantener nitidez vectorial) -->
                                                    <Grid Height="64" Margin="24,0,24,18" Opacity="0" VerticalAlignment="Bottom" x:Name="Ar_BottomPill">
                                                        <!-- Capa 1: Sombra aislada atrás (sin hijos adentro para no rasterizar los textos) -->
                                                        <Border Background="#FFFFFF" CornerRadius="32" IsHitTestVisible="False">
                                                            <Border.Effect>
                                                                <DropShadowEffect BlurRadius="18" Color="Black" Direction="270" Opacity="0.12" ShadowDepth="4"/>
                                                            </Border.Effect>
                                                        </Border>

                                                        <!-- Capa 2: Píldora Real 100% Vectorial (Sin Effect) -->
                                                        <Border Background="#F7FFFFFF" BorderBrush="#1A000000" BorderThickness="1" CornerRadius="32" RenderOptions.ClearTypeHint="Enabled">
                                                            <Grid Margin="6,4">
                                                                <Grid.ColumnDefinitions>
                                                                    <ColumnDefinition Width="*"/>
                                                                    <ColumnDefinition Width="*"/>
                                                                    <ColumnDefinition Width="*"/>
                                                                </Grid.ColumnDefinitions>

                                                                <!-- 1. Recientes -->
                                                                <StackPanel Grid.Column="0" HorizontalAlignment="Center" VerticalAlignment="Center">
                                                                    <Canvas Height="22" HorizontalAlignment="Center" Margin="0,0,0,3" Width="22">
                                                                        <Ellipse Canvas.Left="1.5" Canvas.Top="1.5" Fill="#8E8E93" Height="19" Width="19"/>
                                                                        <Path Data="M 11,6.5 L 11,11.5 L 14.5,11.5" Stroke="#FFFFFF" StrokeEndLineCap="Round" StrokeLineJoin="Round" StrokeStartLineCap="Round" StrokeThickness="1.8"/>
                                                                    </Canvas>
                                                                    <TextBlock FontSize="11.5" FontWeight="Medium" Foreground="#8E8E93" HorizontalAlignment="Center" Text="Recientes"/>
                                                                </StackPanel>

                                                                <!-- 2. Compartido -->
                                                                <StackPanel Grid.Column="1" HorizontalAlignment="Center" VerticalAlignment="Center">
                                                                    <Canvas Height="22" HorizontalAlignment="Center" Margin="0,0,0,3" Width="26">
                                                                        <Ellipse Canvas.Left="5" Canvas.Top="2.5" Fill="#8E8E93" Height="7" Width="7"/>
                                                                        <Path Data="M 1.5,18.5 C 1.5,14 5,12 8.5,12 C 12,12 15.5,14 15.5,18.5 Z" Fill="#8E8E93"/>
                                                                        <Ellipse Canvas.Left="15" Canvas.Top="4" Fill="#AEAEB2" Height="6" Width="6"/>
                                                                        <Path Data="M 13.5,18.5 C 14,15 16,13.2 18.5,13.2 C 21.5,13.2 24,15 24.5,18.5 Z" Fill="#AEAEB2"/>
                                                                    </Canvas>
                                                                    <TextBlock FontSize="11.5" FontWeight="Medium" Foreground="#8E8E93" HorizontalAlignment="Center" Text="Compartido"/>
                                                                </StackPanel>

                                                                <!-- 3. Explorar (Con burbuja Liquid Glass 100% vectorial) -->
                                                                <Grid Grid.Column="2" HorizontalAlignment="Stretch" RenderTransformOrigin="0.5,0.5" VerticalAlignment="Stretch">
                                                                    <Grid.RenderTransform>
                                                                        <ScaleTransform ScaleX="1.0" ScaleY="1.0" x:Name="Ar_PillExplorarScale"/>
                                                                    </Grid.RenderTransform>
                                                                    <!-- Fondo base de la pestaña activa -->
                                                                    <Border Background="#18007AFF" CornerRadius="26"/>
                                                                    <!-- Brillo Liquid Glass al presionar (Sin DropShadowEffect para no pixelar) -->
                                                                    <Border BorderThickness="1.5" CornerRadius="26" Opacity="0" x:Name="Ar_PillExplorarGlow">
                                                                        <Border.Background>
                                                                            <LinearGradientBrush EndPoint="1,1" StartPoint="0,0">
                                                                                <GradientStop Color="#38007AFF" Offset="0.0"/>
                                                                                <GradientStop Color="#1A007AFF" Offset="0.5"/>
                                                                                <GradientStop Color="#3500C7FF" Offset="1.0"/>
                                                                            </LinearGradientBrush>
                                                                        </Border.Background>
                                                                        <Border.BorderBrush>
                                                                            <LinearGradientBrush EndPoint="1,1" StartPoint="0,0">
                                                                                <GradientStop Color="#80007AFF" Offset="0.0"/>
                                                                                <GradientStop Color="#40007AFF" Offset="0.5"/>
                                                                                <GradientStop Color="#805AC8FA" Offset="1.0"/>
                                                                            </LinearGradientBrush>
                                                                        </Border.BorderBrush>
                                                                    </Border>

                                                                    <StackPanel HorizontalAlignment="Center" VerticalAlignment="Center">
                                                                        <Canvas Height="22" HorizontalAlignment="Center" Margin="0,0,0,3" Width="24">
                                                                            <Path Data="M 2,5.5 A 2,2 0 0 1 4,3.5 L 9.5,3.5 L 11.5,5.8 L 20,5.8 A 2,2 0 0 1 22,7.8 L 22,17.5 A 2,2 0 0 1 20,19.5 L 4,19.5 A 2,2 0 0 1 2,17.5 Z" Fill="#007AFF"/>
                                                                        </Canvas>
                                                                        <TextBlock FontSize="11.5" FontWeight="SemiBold" Foreground="#007AFF" HorizontalAlignment="Center" Text="Explorar"/>
                                                                    </StackPanel>
                                                                </Grid>
                                                            </Grid>
                                                        </Border>
                                                    </Grid>

                                                    <Border x:Name="Ar_MenuPopup" Width="250" Background="#FFFFFF" CornerRadius="24" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,20,20,0" RenderTransformOrigin="0.93, 0.09" Opacity="1">
                                                        <Border.RenderTransform><ScaleTransform x:Name="Ar_MenuScale" ScaleX="0.1" ScaleY="0.1"/></Border.RenderTransform>
                                                        <StackPanel Margin="18">
                                                            <Grid Margin="0,0,0,18">
                                                                <Grid.ColumnDefinitions><ColumnDefinition Width="40"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                                <Canvas Grid.Column="0" Width="24" Height="24" HorizontalAlignment="Left" VerticalAlignment="Center">
                                                                    <Path Data="M 4,7 L 4,4 L 7,4 M 17,4 L 20,4 L 20,7 M 4,17 L 4,20 L 7,20 M 17,20 L 20,20 L 20,17" Stroke="#000000" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round"/>
                                                                    <Path Data="M 9,7 L 12.5,7 L 15,9.5 L 15,17 L 9,17 Z" Stroke="#000000" StrokeThickness="1.5" StrokeLineJoin="Round" Fill="Transparent"/>
                                                                    <Path Data="M 12.5,7 L 12.5,9.5 L 15,9.5" Stroke="#000000" StrokeThickness="1.5" StrokeLineJoin="Round" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                                                                </Canvas>
                                                                <TextBlock Grid.Column="1" Text="Escanear documen-&#x0a;tos" FontSize="17.5" Foreground="#000000" LineHeight="22" LineStackingStrategy="BlockLineHeight" VerticalAlignment="Center"/>
                                                            </Grid>
                                                            <Grid Margin="0,0,0,18">
                                                                <Grid.ColumnDefinitions><ColumnDefinition Width="40"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                                <Border Grid.ColumnSpan="2" CornerRadius="8" Margin="-12,-8,-12,-8"><Border.Background><SolidColorBrush x:Name="Ar_HighlightBrush" Color="Transparent"/></Border.Background></Border>
                                                                <Canvas Grid.Column="0" Width="24" Height="24" HorizontalAlignment="Left" VerticalAlignment="Center">
                                                                    <Rectangle Width="16" Height="10" Canvas.Left="4" Canvas.Top="5" RadiusX="2" RadiusY="2" Stroke="#000000" StrokeThickness="1.5" Fill="Transparent"/><Path Data="M 12,15 L 12,20 M 7,20 L 17,20" Stroke="#000000" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/><Ellipse Width="3" Height="3" Canvas.Left="10.5" Canvas.Top="18.5" Fill="#000000"/>
                                                                </Canvas>
                                                                <TextBlock Grid.Column="1" Text="Conectar con&#x0a;el servidor" FontSize="17.5" Foreground="#000000" LineHeight="22" LineStackingStrategy="BlockLineHeight" VerticalAlignment="Center"/>
                                                            </Grid>
                                                            <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="40"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBlock Grid.Column="1" Text="Editar" FontSize="17.5" Foreground="#000000" VerticalAlignment="Center"/></Grid>
                                                        </StackPanel>
                                                    </Border>
                                                    <Border x:Name="Ar_DimOverlay" Background="#000000" Opacity="0" CornerRadius="40" IsHitTestVisible="False"/>
                                                    <Border x:Name="Ar_ServidorView" Opacity="1" Background="#F2F2F7" CornerRadius="40" Padding="20,18,20,24" Margin="0,45,0,0" VerticalAlignment="Stretch">
                                                        <Border.RenderTransform><TranslateTransform x:Name="Ar_ServidorTranslate" X="0" Y="500"/></Border.RenderTransform>
                                                        <Grid>
                                                            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                                                            <Grid Grid.Row="0" Margin="0,4,0,24">
                                                                <Border Width="42" Height="42" CornerRadius="21" Background="#FFFFFF" HorizontalAlignment="Left">
                                                                    <Canvas Width="16" Height="16" HorizontalAlignment="Center" VerticalAlignment="Center"><Path Data="M 2,2 L 14,14 M 14,2 L 2,14" Stroke="#1C1C1E" StrokeThickness="2.4" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/></Canvas>
                                                                </Border>
                                                                <TextBlock Text="Conectar con el servidor" FontSize="18" FontWeight="Bold" Foreground="#111111" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                                                <Border Width="42" Height="42" CornerRadius="21" Background="#007AFF" HorizontalAlignment="Right">
                                                                    <Canvas Width="14" Height="10" HorizontalAlignment="Center" VerticalAlignment="Center" Margin="1,2,0,0"><Path Data="M 0,5 L 5,10 L 14,0" Stroke="#FFFFFF" StrokeThickness="2.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round"/></Canvas>
                                                                </Border>
                                                            </Grid>
                                                            <Border Grid.Row="1" Background="#FFFFFF" CornerRadius="22">
                                                                <Grid Height="54" Margin="18,0,18,0">
                                                                    <Grid.ColumnDefinitions><ColumnDefinition Width="110"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                                                                    <TextBlock Grid.Column="0" Text="Servidor" FontSize="17.5" Foreground="#000000" VerticalAlignment="Center"/>
                                                                    <TextBlock Grid.Column="1" Text="$NombrePC" FontSize="17.5" Foreground="#000000" VerticalAlignment="Center" HorizontalAlignment="Left"/>
                                                                </Grid>
                                                            </Border>
                                                        </Grid>
                                                    </Border>
                                                    <Border x:Name="Ar_CredencialesView" Opacity="1" Background="#F2F2F7" CornerRadius="40" Padding="20,18,20,24" Margin="0,45,0,0" VerticalAlignment="Stretch">
                                                        <Border.RenderTransform><TranslateTransform x:Name="Ar_CredencialesTranslate" X="450" Y="0"/></Border.RenderTransform>
                                                        <Grid>
                                                            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="18"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                                                            <Grid Grid.Row="0" Margin="0,4,0,24">
                                                                <Border Width="42" Height="42" CornerRadius="21" Background="#FFFFFF" HorizontalAlignment="Left" Cursor="Hand">
                                                                    <Canvas Width="16" Height="16" HorizontalAlignment="Center" VerticalAlignment="Center"><Path Data="M 2,2 L 14,14 M 14,2 L 2,14" Stroke="#1C1C1E" StrokeThickness="2.4" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/></Canvas>
                                                                </Border>
