                                            <Ellipse Width="16" Height="16" Fill="#FFFFFF" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                        </Grid>
                                    </Grid>
                                </Border>
                                <Canvas Width="60" Height="60">
                                    <TextBlock x:Name="Fo_AppIconText" Text="Fotos" Width="100" Canvas.Left="-20" Canvas.Top="68" Foreground="Black" FontWeight="Medium" FontSize="13" TextAlignment="Center"/>
                                </Canvas>
                            </Grid>
                        </Grid>
                    </Grid>

<!-- CONTENEDOR QR -->
                    <Grid Grid.Column="1" x:Name="QrContainer" Background="Transparent" HorizontalAlignment="Center" VerticalAlignment="Center" Width="180" Height="180" Panel.ZIndex="3000" RenderTransformOrigin="0.5, 0.5">
                        <Grid.RenderTransform>
                            <TransformGroup>
                                <ScaleTransform x:Name="ScaleQr" ScaleX="1.0" ScaleY="1.0"/>
                                <TranslateTransform x:Name="TransQr" X="0" Y="0"/>
                            </TransformGroup>
                        </Grid.RenderTransform>
                        <!-- Capa 1: Sombra general de la tarjeta -->
                        <Border Background="White" CornerRadius="24" IsHitTestVisible="False">
                            <Border.Effect>
                                <DropShadowEffect Color="Black" Direction="270" ShadowDepth="4" BlurRadius="16" Opacity="0.12"/>
                            </Border.Effect>
                        </Border>
                        <!-- Capa 2: Tarjeta del QR -->
                        <Rectangle RadiusX="24" RadiusY="24" IsHitTestVisible="False">
                            <Rectangle.Fill>
                                <ImageBrush x:Name="ImgQrCodeBrush" Stretch="UniformToFill"/>
                            </Rectangle.Fill>
                        </Rectangle>
                        <!-- Capa 3: Etiqueta 'QR' al achicarse a ícono -->
                        <Canvas Height="180" IsHitTestVisible="False" Width="180">
                            <Border Canvas.Left="-60" Canvas.Top="204" Width="300" Background="#FFF5F5F7" RenderOptions.ClearTypeHint="Enabled" Opacity="0" x:Name="QrText">
                                <TextBlock FontSize="39" FontWeight="Medium" Foreground="#1D1D1F" Text="QR" TextAlignment="Center"/>
                            </Border>
                        </Canvas>
                    </Grid>
                    <Canvas Grid.Column="1" Width="180" Height="180" HorizontalAlignment="Center" VerticalAlignment="Center" IsHitTestVisible="False" Panel.ZIndex="2999">
                        <Border x:Name="QrSubText" Canvas.Left="-35" Canvas.Top="195" Width="250" Background="#FFF5F5F7" RenderOptions.ClearTypeHint="Enabled">
                            <TextBlock Text="Escane&#x00E1; para obtener el atajo" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12.5" FontWeight="Medium" Foreground="#1D1D1F" TextAlignment="Center"/>
                        </Border>
                    </Canvas>

                  </Grid>

<!-- PANEL DE INFORMACIÓN Y FUNCIONES DEL SISTEMA (?) -->
                        <Grid x:Name="AyudaFullPanel" Grid.Row="0" Grid.RowSpan="7" Height="405" Opacity="0" Visibility="Collapsed" IsHitTestVisible="False" Panel.ZIndex="550" VerticalAlignment="Top" RenderTransformOrigin="0.5,0.5" TextOptions.TextHintingMode="Fixed">
                            <Grid.RenderTransform>
                                <TransformGroup>
                                    <ScaleTransform ScaleX="1" ScaleY="1"/>
                                    <TranslateTransform X="0" Y="0"/>
                                </TransformGroup>
                            </Grid.RenderTransform>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="*"/>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="30"/>
                            </Grid.RowDefinitions>

                            <!-- Título del panel -->
                            <Border Grid.Row="0" Background="#FFF5F5F7" RenderOptions.ClearTypeHint="Enabled" HorizontalAlignment="Center" Margin="0,4,0,10">
                                <TextBlock Text="Qu&#x00E9; hace cada funci&#x00F3;n en el sistema" FontFamily="Segoe UI Variable Display, Segoe UI" FontSize="18" FontWeight="SemiBold" Foreground="#1D1D1F"/>
                            </Border>

                            <!-- Lista deslizable de tarjetas -->
                            <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Width="480" Margin="0,0,0,8" PanningMode="VerticalOnly" UseLayoutRounding="True" SnapsToDevicePixels="True">
                                <ScrollViewer.Resources>
                                    <Style TargetType="ScrollBar">
                                        <Setter Property="Width" Value="6"/>
                                        <Setter Property="Background" Value="Transparent"/>
                                        <Setter Property="Template">
                                            <Setter.Value>
                                                <ControlTemplate TargetType="ScrollBar">
                                                    <Grid Background="Transparent">
                                                        <Track x:Name="PART_Track" IsDirectionReversed="true">
                                                            <Track.Thumb>
                                                                <Thumb>
                                                                    <Thumb.Template>
                                                                        <ControlTemplate TargetType="Thumb">
                                                                            <Border Background="#40000000" CornerRadius="3"/>
                                                                        </ControlTemplate>
                                                                    </Thumb.Template>
                                                                </Thumb>
                                                            </Track.Thumb>
                                                        </Track>
                                                    </Grid>
                                                </ControlTemplate>
                                            </Setter.Value>
                                        </Setter>
                                    </Style>
                                </ScrollViewer.Resources>

                                <StackPanel Margin="0,0,8,0" UseLayoutRounding="True" SnapsToDevicePixels="True">
                                    <!-- 1. Instalar -->
                                    <Border Background="#FFFFFF" BorderBrush="#E5E5EA" BorderThickness="1" CornerRadius="8" Padding="12,9" Margin="0,0,0,8" RenderOptions.ClearTypeHint="Enabled">
                                        <StackPanel>
                                            <TextBlock Text="Instalar (manual o v&#x00ED;a PowerShell)" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" FontWeight="SemiBold" Foreground="#007AFF" Margin="0,0,0,3"/>
                                            <TextBlock Text="Copia los archivos necesarios a %APPDATA%\AirDrop. Crea el acceso directo en el Men&#x00FA; de Inicio, registra el ID de notificaciones en HKCU:\Software\Classes\AppUserModelId\AirDrop.App y crea la tarea 'AirDrop' para iniciar el script al iniciar sesi&#x00F3;n." FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12" Foreground="#48484A" TextWrapping="Wrap" LineHeight="17"/>
                                        </StackPanel>
                                    </Border>

                                    <!-- 2. Examinar (...) y Carpeta compartida -->
                                    <Border Background="#FFFFFF" BorderBrush="#E5E5EA" BorderThickness="1" CornerRadius="8" Padding="12,9" Margin="0,0,0,8" RenderOptions.ClearTypeHint="Enabled">
                                        <StackPanel>
                                            <TextBlock Text="Seleccionar carpeta (...) | Carpeta compartida" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" FontWeight="SemiBold" Foreground="#1D1D1F" Margin="0,0,0,3"/>
                                            <TextBlock Text="El bot&#x00F3;n '...' define la carpeta que vigila el script en segundo plano. Al activar 'Carpeta compartida', asigna permisos NTFS de modificaci&#x00F3;n al grupo Todos (S-1-1-0), comparte la carpeta por red SMB, pasa la red actual a perfil Privado, habilita el uso compartido de archivos en el Firewall Privado (bloque&#x00E1;ndolo en redes P&#x00FA;blicas) y activa en el Registro (HKLM) la protecci&#x00F3;n por contrase&#x00F1;a con cifrado NTLM de 128 bits." FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12" Foreground="#48484A" TextWrapping="Wrap" LineHeight="17"/>
                                        </StackPanel>
                                    </Border>

                                    <!-- 3. Iniciar con Windows -->
                                    <Border Background="#FFFFFF" BorderBrush="#E5E5EA" BorderThickness="1" CornerRadius="8" Padding="12,9" Margin="0,0,0,8" RenderOptions.ClearTypeHint="Enabled">
                                        <StackPanel>
                                            <TextBlock Text="Iniciar con Windows" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" FontWeight="SemiBold" Foreground="#1D1D1F" Margin="0,0,0,3"/>
                                            <TextBlock Text="Habilita o deshabilita la tarea programada 'AirDrop' en Windows para que el script arranque autom&#x00E1;ticamente en segundo plano al iniciar sesi&#x00F3;n." FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12" Foreground="#48484A" TextWrapping="Wrap" LineHeight="17"/>
                                        </StackPanel>
                                    </Border>

                                    <!-- 4. Crear | Eliminar credenciales -->
                                    <Border Background="#FFFFFF" BorderBrush="#E5E5EA" BorderThickness="1" CornerRadius="8" Padding="12,9" Margin="0,0,0,8" RenderOptions.ClearTypeHint="Enabled">
                                        <StackPanel>
                                            <TextBlock Text="Crear credenciales | Eliminar credenciales" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" FontWeight="SemiBold" Foreground="#1D1D1F" Margin="0,0,0,3"/>
                                            <TextBlock Text="Crea una cuenta de usuario local en Windows (sin vencimiento de contrase&#x00F1;a) dentro del grupo Usuarios para que tu iPhone pueda autenticarse por SMB, y guarda los datos en credentials.json. 'Eliminar credenciales' borra ese usuario local de Windows." FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12" Foreground="#48484A" TextWrapping="Wrap" LineHeight="17"/>
                                        </StackPanel>
                                    </Border>

                                    <!-- 5. Desinstalar (Con el botón integrado al estilo Configuración de macOS) -->
                                    <Border Background="#FFFFFF" BorderBrush="#E5E5EA" BorderThickness="1" CornerRadius="8" Padding="12,9" Margin="0,0,0,2" RenderOptions.ClearTypeHint="Enabled">
                                        <StackPanel>
                                            <Grid Margin="0,0,0,5">
                                                <TextBlock Text="Desinstalar" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="13" FontWeight="SemiBold" Foreground="#FF3B30" VerticalAlignment="Center" HorizontalAlignment="Left"/>
                                                <Button x:Name="BtnDesinstalar" Content="Desinstalar AirDrop" Foreground="#FF3B30" Style="{StaticResource BotonMacSecundario}" FontSize="12" Padding="10,3" Margin="0" HorizontalAlignment="Right" VerticalAlignment="Center"/>
                                            </Grid>
                                            <TextBlock Text="Deja de compartir la carpeta en red (SMB), elimina el usuario local creado, borra la tarea programada, limpia el Registro de notificaciones, cierra el script en segundo plano, quita el acceso directo del Men&#x00FA; de Inicio y elimina %APPDATA%\AirDrop." FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12" Foreground="#48484A" TextWrapping="Wrap" LineHeight="17" Margin="0,0,0,5"/>
                                            <TextBlock Text="&#x2022; Qu&#x00E9; no revierte: Tu carpeta y los archivos recibidos quedan intactos. La conexi&#x00F3;n de red permanece como 'Privada', se conservan los permisos NTFS locales de esa carpeta y quedan activas las reglas seguras del Firewall y de cifrado de 128 bits en Windows." FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12" Foreground="#6E6E73" TextWrapping="Wrap" LineHeight="17" TextOptions.TextHintingMode="Fixed"/>
                                        </StackPanel>
                                    </Border>
                                </StackPanel>
                            </ScrollViewer>

                            <!-- Link al Repositorio de GitHub -->
                            <Button x:Name="BtnGitHubRepo" Grid.Row="2" Cursor="Hand" HorizontalAlignment="Center" Margin="0,2,0,8" Background="Transparent" BorderThickness="0">
                                <Button.Template>
                                    <ControlTemplate TargetType="Button">
                                        <Border x:Name="RepoPill" Background="Transparent" CornerRadius="6" Padding="8,3">
                                            <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                                                <Canvas Width="14" Height="14" Margin="0,0,6,0" VerticalAlignment="Center">
                                                    <Path Data="M 7,0.5 C 3.41,0.5 0.5,3.41 0.5,7 C 0.5,9.87 2.36,12.3 4.94,13.16 C 5.27,13.22 5.39,13.02 5.39,12.85 L 5.39,11.66 C 3.58,12.05 3.2,10.79 3.2,10.79 C 2.9,10.04 2.48,9.84 2.48,9.84 C 1.89,9.43 2.52,9.44 2.52,9.44 C 3.17,9.49 3.51,10.11 3.51,10.11 C 4.09,11.1 5.03,10.81 5.4,10.65 C 5.46,10.23 5.63,9.95 5.81,9.79 C 4.37,9.63 2.85,9.07 2.85,6.58 C 2.85,5.87 3.1,5.29 3.52,4.83 C 3.45,4.67 3.23,4.01 3.58,3.12 C 3.58,3.12 4.13,2.94 5.37,3.78 C 5.89,3.64 6.45,3.57 7,3.57 C 7.55,3.57 8.11,3.64 8.63,3.78 C 9.87,2.94 10.42,3.12 10.42,3.12 C 10.77,4.01 10.55,4.67 10.48,4.83 C 10.9,5.29 11.15,5.87 11.15,6.58 C 11.15,9.08 9.63,9.63 8.18,9.79 C 8.41,9.99 8.62,10.39 8.62,11.01 L 8.62,12.85 C 8.62,13.02 8.74,13.23 9.07,13.16 C 11.64,12.3 13.5,9.87 13.5,7 C 13.5,3.41 10.59,0.5 7,0.5 Z" Fill="#007AFF"/>
                                                </Canvas>
                                                <TextBlock x:Name="RepoText" Text="github.com/brandown02/AirDrop-like-thing-for-Windows" FontFamily="Segoe UI Variable Text, Segoe UI" FontSize="12" FontWeight="Medium" Foreground="#007AFF" VerticalAlignment="Center"/>
                                            </StackPanel>
                                        </Border>
                                        <ControlTemplate.Triggers>
                                            <Trigger Property="IsMouseOver" Value="True">
                                                <Setter TargetName="RepoPill" Property="Background" Value="#12007AFF"/>
                                                <Setter TargetName="RepoText" Property="TextDecorations" Value="Underline"/>
                                            </Trigger>
                                        </ControlTemplate.Triggers>
                                    </ControlTemplate>
                                </Button.Template>
                            </Button>

                            <!-- Botón Volver alineado abajo -->
                            <Grid Grid.Row="3" Margin="0,-18,0,-18">
                                <Button x:Name="BtnVolverAyuda" Content="Volver" Style="{StaticResource BotonMacSecundario}" Width="105" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Grid>
                        </Grid>

                    </Grid>
                </Grid>
            </Border>
        </Border>
    </Grid>
</Window>
"@

$reader = (New-Object System.Xml.XmlNodeReader $xaml)
$global:Window = [Windows.Markup.XamlReader]::Load($reader)

$global:Window.Add_MouseLeftButtonDown({ $global:Window.DragMove() })

$sbCerrar = $global:Window.FindResource("AnimacionCerrar")
$global:Window.FindName("BtnCerrarVentana").Add_Click({ 
    $global:Window.FindName("BordePrincipal").IsHitTestVisible = $false
    $sbCerrar.Begin($global:Window, $true)
    Wait-Wpf -Milliseconds 150
    $global:Window.Close()
})

$sbMinimizar = $global:Window.FindResource("AnimacionMinimizar")
$global:Window.FindName("BtnMinimizarVentana").Add_Click({ 
    $global:Window.FindName("BordePrincipal").IsHitTestVisible = $false
    $sbMinimizar.Begin($global:Window, $true)
    
    if ($global:TimerMin) { $global:TimerMin.Stop() }
    $global:TimerMin = New-Object System.Windows.Threading.DispatcherTimer
    $global:TimerMin.Interval = [TimeSpan]::FromMilliseconds(150)
    $global:TimerMin.Add_Tick({
        $global:TimerMin.Stop()
        $global:Window.WindowState = [System.Windows.WindowState]::Minimized
    })
    $global:TimerMin.Start()
})

$global:sbRestaurar = $global:Window.FindResource("AnimacionRestaurar")
$global:Window.Add_StateChanged({
    if ($global:Window.WindowState -eq [System.Windows.WindowState]::Normal) {
        $global:Window.FindName("BordePrincipal").IsHitTestVisible = $true
        $global:sbRestaurar.Begin($global:Window, $true)
        $global:Window.Activate()
    }
})

$global:Window.Add_Closed({
    # Asegura que el cursor de Windows vuelva a la normalidad al cerrar
    try { [Win32]::SystemParametersInfo(0x0057, 0, [IntPtr]::Zero, 0) | Out-Null } catch {}
})

$global:Window.Add_Activated({
    # No ejecutar si est  minimizada, si a n no termin  la carga inicial o si se est  ejecutando UAC
    if ($global:Window.WindowState -eq [System.Windows.WindowState]::Minimized) { return }
    if (-not $global:CargaInicialCompleta -or $global:EjecutandoAdmin) { return }

    if ($isInstalled) {
        if ($global:TimerCheckActivate) { $global:TimerCheckActivate.Stop() }
        $global:TimerCheckActivate = New-Object System.Windows.Threading.DispatcherTimer
        $global:TimerCheckActivate.Interval = [TimeSpan]::FromMilliseconds(250)
        $global:TimerCheckActivate.Add_Tick({
            $global:TimerCheckActivate.Stop()
            $config = Get-AppConfig
            if ($config.Carpeta -and (Test-Path $config.Carpeta)) {
                $isShared = Test-AirDropConditions -Path $config.Carpeta
                $global:IgnorarClick = $true
                $ChkCompartida.IsChecked = $isShared
                $global:IgnorarClick = $false

                if ($isShared -and [string]::IsNullOrWhiteSpace($config.CarpetaActiva)) {
                    $config.CarpetaActiva = $config.Carpeta
                    Save-AppConfig $config
                }
            }
        })
        $global:TimerCheckActivate.Start()
    }
})

$BordePrincipal = $global:Window.FindName("BordePrincipal")
$BtnLogo = $global:Window.FindName("BtnLogo")
$LogoImage = $global:Window.FindName("LogoImage")
$TxtAirDropTitle = $global:Window.FindName("TxtAirDropTitle")
$BtnExaminar = $global:Window.FindName("BtnExaminar")
$TxtRuta = $global:Window.FindName("TxtRuta")

$RowCuerpo = $global:Window.FindName("RowCuerpo")
$RowEspacioBotones = $global:Window.FindName("RowEspacioBotones")
$RowEspacioTitulo = $global:Window.FindName("RowEspacioTitulo")

$BodyInstalar = $global:Window.FindName("BodyInstalar")
$BotonesInstalar = $global:Window.FindName("BotonesInstalar")
$BtnInstalar = $global:Window.FindName("BtnInstalar")

$BodyPrincipal = $global:Window.FindName("BodyPrincipal")
$BotonesPrincipal = $global:Window.FindName("BotonesPrincipal")
$BtnDesinstalar = $global:Window.FindName("BtnDesinstalar")
$BtnAtajo = $global:Window.FindName("BtnAtajo")

$BtnCredenciales = $global:Window.FindName("BtnCredenciales")
$BtnEliminarCredenciales = $global:Window.FindName("BtnEliminarCredenciales")
$BtnVolver = $global:Window.FindName("BtnVolver")
$BtnContinuar = $global:Window.FindName("BtnContinuar")
$TxtUsuario = $global:Window.FindName("TxtUsuario")
$TxtPassword = $global:Window.FindName("TxtPassword")
$BodyCredenciales = $global:Window.FindName("BodyCredenciales")
$BotonesCredenciales = $global:Window.FindName("BotonesCredenciales")

# ==========================================================
# LÓGICA DE PLACEHOLDERS ESTILO COCOA (SE OCULTAN AL ESCRIBIR)
# ==========================================================
$global:PlaceholderPass     = "Escribir contrase$([char]0x00F1)a..."
$PlaceholderUsuario         = $global:Window.FindName("PlaceholderUsuario")
$PlaceholderPassword        = $global:Window.FindName("PlaceholderPassword")

$global:BrushCursorActivo = (New-Object System.Windows.Media.BrushConverter).ConvertFromString("#1D1D1F")

$TxtUsuario.Add_TextChanged({
    $vacio = [string]::IsNullOrEmpty($TxtUsuario.Text)
    if ($PlaceholderUsuario) {
        $PlaceholderUsuario.Visibility = if ($vacio) { "Visible" } else { "Collapsed" }
    }
    $TxtUsuario.CaretBrush = if ($vacio) { [System.Windows.Media.Brushes]::Transparent } else { $global:BrushCursorActivo }
})

$TxtPassword.Add_TextChanged({
    $vacio = [string]::IsNullOrEmpty($TxtPassword.Text)
    if ($PlaceholderPassword) {
        $PlaceholderPassword.Visibility = if ($vacio) { "Visible" } else { "Collapsed" }
    }
    $TxtPassword.CaretBrush = if ($vacio) { [System.Windows.Media.Brushes]::Transparent } else { $global:BrushCursorActivo }
})

$TxtUsuario.Add_GotFocus({
    if ($TxtUsuario.IsReadOnly) { return }
    if ($TxtUsuario.Text -eq "No se admiten espacios") {
        if ($global:TimerEspacios) { $global:TimerEspacios.Stop() }
        
        $animOut = New-Object System.Windows.Media.Animation.DoubleAnimation
        $animOut.From = 1.0; $animOut.To = 0.0
        $animOut.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
        $TxtUsuario.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animOut)
        
        if ($global:timerClick) { $global:timerClick.Stop() }
        $global:timerClick = New-Object System.Windows.Threading.DispatcherTimer
        $global:timerClick.Interval = [TimeSpan]::FromMilliseconds(300)
        $global:timerClick.Add_Tick({
            $global:timerClick.Stop()
            $TxtUsuario.Text = $global:UserConEspacios
            $TxtUsuario.Foreground = "#1D1D1F"
            
            $animIn = New-Object System.Windows.Media.Animation.DoubleAnimation
            $animIn.From = 0.0; $animIn.To = 1.0
            $animIn.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
            $TxtUsuario.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animIn)
        })
        $global:timerClick.Start()
    }
})

$BodyDesinstalar = $global:Window.FindName("BodyDesinstalar")
$BotonesDesinstalar = $global:Window.FindName("BotonesDesinstalar")
$BtnConfirmarDesinstalar = $global:Window.FindName("BtnConfirmarDesinstalar")
$BtnCancelarDesinstalar = $global:Window.FindName("BtnCancelarDesinstalar")

$AtajosFullPanel = $global:Window.FindName("AtajosFullPanel")
$BtnAyuda       = $global:Window.FindName("BtnAyuda")
$AyudaFullPanel = $global:Window.FindName("AyudaFullPanel")
$BtnVolverAyuda = $global:Window.FindName("BtnVolverAyuda")
$BtnGitHubRepo  = $global:Window.FindName("BtnGitHubRepo")

$BtnGitHubRepo.Add_Click({
    Start-Process "https://github.com/brandown02/AirDrop-like-thing-for-Windows"
})

$BtnAyuda.Add_Click({
    if ($global:AnimacionEnCurso) { return }

    # Si ya está abierto el panel de Ayuda, al tocar '?' vuelve al menú anterior
    if ($AyudaFullPanel.Visibility -eq "Visible" -and $AyudaFullPanel.Opacity -gt 0.5) {
        $BtnVolverAyuda.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
        return
    }

    Fijar-LayoutPrincipal

    # Detectar desde qué panel se abrió para volver exactamente al mismo lugar
    if ($AtajosFullPanel.Visibility -eq "Visible" -and $AtajosFullPanel.Opacity -gt 0.5) {
        $global:PanelPrevioBody     = $AtajosFullPanel
        $global:PanelPrevioBotones  = $AtajosFullPanel
        $global:TeniasHeaderVisible = $false
    } elseif ($BodyCredenciales.Visibility -eq "Visible" -and $BodyCredenciales.Opacity -gt 0.5) {
        $global:PanelPrevioBody     = $BodyCredenciales
        $global:PanelPrevioBotones  = $BotonesCredenciales
        $global:TeniasHeaderVisible = $true
    } elseif ($BodyDesinstalar.Visibility -eq "Visible" -and $BodyDesinstalar.Opacity -gt 0.5) {
        $global:PanelPrevioBody     = $BodyDesinstalar
        $global:PanelPrevioBotones  = $BotonesDesinstalar
        $global:TeniasHeaderVisible = $true
    } elseif ($BodyConfirmarRed.Visibility -eq "Visible" -and $BodyConfirmarRed.Opacity -gt 0.5) {
        $global:PanelPrevioBody     = $BodyConfirmarRed
        $global:PanelPrevioBotones  = $BotonesConfirmarRed
        $global:TeniasHeaderVisible = $true
    } else {
        $global:PanelPrevioBody     = $BodyPrincipal
        $global:PanelPrevioBotones  = $BotonesPrincipal
        $global:TeniasHeaderVisible = $true
    }

    if ($global:TeniasHeaderVisible) {
        Animar-HeaderMac -Mostrar $false
    }
    Transicion-Paneles -OcultarBody $global:PanelPrevioBody -OcultarBotones $global:PanelPrevioBotones -MostrarBody $AyudaFullPanel -MostrarBotones $AyudaFullPanel -Direccion 1
})

$BtnVolverAyuda.Add_Click({
    $targetBody    = if ($global:PanelPrevioBody) { $global:PanelPrevioBody } else { $BodyPrincipal }
    $targetBotones = if ($global:PanelPrevioBotones) { $global:PanelPrevioBotones } else { $BotonesPrincipal }

    if ($global:TeniasHeaderVisible -ne $false) {
        Animar-HeaderMac -Mostrar $true
    }
    Transicion-Paneles -OcultarBody $AyudaFullPanel -OcultarBotones $AyudaFullPanel -MostrarBody $targetBody -MostrarBotones $targetBotones -Direccion -1
})
$BtnVolverAtajos = $global:Window.FindName("BtnVolverAtajos")

# BOTONES DE APPS (IZQUIERDA)
$BtnAppArchivos = $global:Window.FindName("BtnAppArchivos")
$ImgAppArchivos = $global:Window.FindName("ImgAppArchivos")
$TransArchivos  = $global:Window.FindName("TransArchivos")

$BtnAppAtajos = $global:Window.FindName("BtnAppAtajos")
$ImgAppAtajos = $global:Window.FindName("ImgAppAtajos")
$TransAtajos  = $global:Window.FindName("TransAtajos")

$BtnAppFotos = $global:Window.FindName("BtnAppFotos")
$ImgAppFotos = $global:Window.FindName("ImgAppFotos")
$TransFotos  = $global:Window.FindName("TransFotos")

# CONTENEDORES DE ANIMACIONES (DERECHA)
$Ar_AnimacionContainer = $global:Window.FindName("Ar_AnimacionContainer")
$At_AnimacionContainer = $global:Window.FindName("At_AnimacionContainer")
$Fo_AnimacionContainer = $global:Window.FindName("Fo_AnimacionContainer")
