$global:Window.Add_Loaded({
    try { [Win32]::SystemParametersInfo(0x0057, 0, [IntPtr]::Zero, 0) | Out-Null } catch {}

    try {
        if (Test-Path $imgDest) {
            $bitmap = New-Object System.Windows.Media.Imaging.BitmapImage
            $bitmap.BeginInit()
            $bitmap.UriSource = New-Object System.Uri($imgDest)
            $bitmap.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
            $bitmap.EndInit()
            $LogoImage.Source = $bitmap
            
            if (Test-Path $icoDest) {
                $global:Window.Icon = [System.Windows.Media.Imaging.BitmapFrame]::Create((New-Object System.Uri($icoDest, [System.UriKind]::Absolute)))
            }
        } else {
            Set-WpfImage $imageBase64 $LogoImage
            if ($LogoImage.Source) { $global:Window.Icon = $LogoImage.Source }
        }
    } catch { }

    Set-WpfImage $Base64_AppArchivos $ImgAppArchivos
    Set-WpfImage $Base64_AppArchivos $global:Window.FindName("Ar_AppIconImage")
    if (-not [string]::IsNullOrWhiteSpace($Base64_AppArchivos)) {
        $global:Window.FindName("Ar_AppIconGraphic").Background = [System.Windows.Media.Brushes]::Transparent
    }

    Set-WpfImage $Base64_AppAtajos $ImgAppAtajos
    Set-WpfImage $Base64_AppAtajos $global:Window.FindName("At_AppIconImage")

    Set-WpfImage $Base64_AppFotos $ImgAppFotos
    Set-WpfImage $Base64_AppFotos $global:Window.FindName("Fo_AppIconGraphic") $global:Window.FindName("Fo_AppIconVector")

    Set-WpfImage $imageBase64 $global:Window.FindName("Fo_AirDropImageBg") $global:Window.FindName("Fo_AirDropVectorBg")
    Set-WpfImage $Base64_AppAtajos $global:Window.FindName("Fo_AtajosImageBg") $global:Window.FindName("Fo_AtajosVectorBg")
    Set-WpfImage $Base64_AppAtajos $global:Window.FindName("Fo_MenuAtajosImageBg") $global:Window.FindName("Fo_MenuAtajosVectorBg")
    Set-WpfImage $Base64_AppAtajos $global:Window.FindName("Fo_ModalAtajosImageBg") $global:Window.FindName("Fo_ModalAtajosVectorBg")

    Set-WpfImage $Base64_CarpetaiOS $global:Window.FindName("At_CarpetaAirDropImage") $global:Window.FindName("At_CarpetaAirDropVector")
