    Set-QrCodeFromUrl $UrlAtajoQR $ImgQrCodeBrush
})

$isInstalled = if ($PSCommandPath) { ((Split-Path $PSCommandPath -Parent) -eq $appDataFolder) } else { $false }
$global:CargaInicialCompleta = $false

if ($isInstalled) {
    $BordePrincipal.Height = [double]::NaN

    if ($BtnAyuda) { $BtnAyuda.Visibility = "Visible" }

    $BodyInstalar.Visibility = "Collapsed"
    $BotonesInstalar.Visibility = "Collapsed"

    $BodyPrincipal.Visibility = "Visible"
    $BodyPrincipal.Opacity = 1
    $BodyPrincipal.IsHitTestVisible = $true

    $BotonesPrincipal.Visibility = "Visible"
    $BotonesPrincipal.Opacity = 1
    $BotonesPrincipal.IsHitTestVisible = $true
    
    $config = Get-AppConfig
    if ($config.Usuario) {
        $BtnCredenciales.Content = "Ver credenciales"
        $BtnCredenciales.Style = $global:Window.FindResource("BotonMacSecundario")
        $BtnAtajo.Style = $global:Window.FindResource("BotonMacPrimario")
    } else {
        $BtnCredenciales.Content = "Crear credenciales"
        $BtnCredenciales.Style = $global:Window.FindResource("BotonMacPrimario")
        $BtnAtajo.Style = $global:Window.FindResource("BotonMacSecundario")
    }
    if ($config.Carpeta) { $TxtRuta.Text = $config.Carpeta }

    [System.Windows.Input.Mouse]::OverrideCursor = [System.Windows.Input.Cursors]::AppStarting

    $global:Window.Add_ContentRendered({
        $timerInit = New-Object System.Windows.Threading.DispatcherTimer
        $timerInit.Interval = [TimeSpan]::FromMilliseconds(50)
        $timerInit.Add_Tick({
            $this.Stop()
            try {
                try {
                    $sch = New-Object -ComObject "Schedule.Service"
                    $sch.Connect()
                    $taskObj = $sch.GetFolder("\").GetTask("AirDrop")
                    $global:IgnorarClickWin = $true
                    $ChkWindows.IsChecked = [bool]$taskObj.Enabled
                    $global:IgnorarClickWin = $false
                } catch {
                    $global:IgnorarClickWin = $true
                    $ChkWindows.IsChecked = $false
                    $global:IgnorarClickWin = $false
                }

                $cfgActual = Get-AppConfig
                if ($cfgActual.Carpeta -and (Test-Path -LiteralPath $cfgActual.Carpeta)) {
                    $isShared = Test-AirDropConditions -Path $cfgActual.Carpeta
                    $global:IgnorarClick = $true
                    $ChkCompartida.IsChecked = $isShared
                    $global:IgnorarClick = $false
                    
                    if ($isShared -and [string]::IsNullOrWhiteSpace($cfgActual.CarpetaActiva)) {
                        $cfgActual.CarpetaActiva = $cfgActual.Carpeta
                        Save-AppConfig $cfgActual
                    }

                    if (Test-Path $vbsMonitorPath) {
                        $monRunning = Get-CimInstance Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" | Where-Object { $_.CommandLine -match "-MonitorBackground" }
                        if (-not $monRunning) {
                            Start-Process wscript.exe -ArgumentList "`"$vbsMonitorPath`""
                        }
                    }
                }
            } finally {
                [System.Windows.Input.Mouse]::OverrideCursor = $null
                $global:CargaInicialCompleta = $true
            }
        })
        $timerInit.Start()
    })
} else {
    # ACÁ ES DONDE SE CONFIGURA EL INSTALADOR MANUAL
    $BordePrincipal.Height = [double]::NaN
    
    if ($BtnAyuda) { $BtnAyuda.Visibility = "Collapsed" }

    $BodyPrincipal.Visibility = "Collapsed"
    $BotonesPrincipal.Visibility = "Collapsed"

    $RowCuerpo.Height = New-Object System.Windows.GridLength(0)
    $RowEspacioBotones.Height = New-Object System.Windows.GridLength(0)
    $RowEspacioTitulo.Height = New-Object System.Windows.GridLength(18)

    $BodyInstalar.Visibility = "Visible"
    $BodyInstalar.Opacity = 1
    $BodyInstalar.IsHitTestVisible = $true

    $BotonesInstalar.Visibility = "Visible"
    $BotonesInstalar.Opacity = 1
    $BotonesInstalar.IsHitTestVisible = $true
    $global:CargaInicialCompleta = $true
}

$BtnLogo.Add_Click({
    try {
        if (Test-Path $audioDest) {
            $player = New-Object System.Media.SoundPlayer $audioDest
            $player.Play()
        } else {
            if (-not [string]::IsNullOrWhiteSpace($audioBase64)) {
                $cleanAudio = $audioBase64 -replace "^data:.*;base64,", ""
                $bytesAudio = [Convert]::FromBase64String($cleanAudio)
                $msAudio = New-Object System.IO.MemoryStream($bytesAudio, 0, $bytesAudio.Length)
                $player = New-Object System.Media.SoundPlayer $msAudio
                $player.Play()
            }
        }
    } catch { }
})

$global:MainLayoutRowsFijadas = $false
$global:MainLayoutRowHeights = $null

function Alinear-VolverAtajos {
    try {
        $global:Window.UpdateLayout()

        if ($BtnAtajo -and $BtnVolverAtajos -and $AtajosFullPanel) {
            $parent = $AtajosFullPanel.Parent
            if ($parent) {
                $pBtn = $BtnAtajo.TransformToAncestor($parent).Transform([System.Windows.Point]::new(0, 0))
                $pPanel = $AtajosFullPanel.TransformToAncestor($parent).Transform([System.Windows.Point]::new(0, 0))

                $offsetBtn = [double]$BotonesPrincipal.Margin.Top
                $offsetPanel = [double]$AtajosFullPanel.Margin.Top

                $top = [Math]::Round([Math]::Max(0.0, ($pBtn.Y - $offsetBtn) - ($pPanel.Y - $offsetPanel)))

                $BtnVolverAtajos.VerticalAlignment = "Top"
                $BtnVolverAtajos.Margin = [System.Windows.Thickness]::new(0, $top, 0, 0)
                if ($BtnAtajo.ActualHeight -gt 0) {
                    $BtnVolverAtajos.Height = $BtnAtajo.ActualHeight
                }
            }
        }
    } catch { }
}

function Posicionar-AppsLaterales {
    try {
        $global:Window.UpdateLayout()
        if (-not $AtajosFullPanel -or -not $BtnAppAtajos -or -not $BtnAppArchivos -or -not $BtnAppFotos) { return }

        $hPanel = [double]$AtajosFullPanel.ActualHeight
        if ($hPanel -le 0) { $hPanel = 405 }

        $hAtajos = [double]$BtnAppAtajos.ActualHeight
        if ($hAtajos -le 0) { $hAtajos = 60 }

        $hArchivos = [double]$BtnAppArchivos.ActualHeight
        if ($hArchivos -le 0) { $hArchivos = 60 }

        $hFotos = [double]$BtnAppFotos.ActualHeight
        if ($hFotos -le 0) { $hFotos = 60 }

        $topAtajos = [Math]::Round([Math]::Max(0.0, ($hPanel - $hAtajos) / 2.0))
        $gap = 35.0
        $topArchivos = [Math]::Round([Math]::Max(0.0, $topAtajos - $gap - $hArchivos))
        $topFotos = [Math]::Round([Math]::Min([Math]::Max(0.0, $hPanel - $hFotos), $topAtajos + $hAtajos + $gap))

        $BtnAppAtajos.VerticalAlignment = "Top"
        $BtnAppAtajos.Margin = [System.Windows.Thickness]::new(0, $topAtajos, 0, 0)

        $BtnAppArchivos.VerticalAlignment = "Top"
        $BtnAppArchivos.Margin = [System.Windows.Thickness]::new(0, $topArchivos, 0, 0)

        $BtnAppFotos.VerticalAlignment = "Top"
        $BtnAppFotos.Margin = [System.Windows.Thickness]::new(0, $topFotos, 0, 0)

        if ($TransAtajos) { $TransAtajos.Y = 0 }
    } catch { }
}

function Fijar-LayoutPrincipal {
    if ($global:MainLayoutRowsFijadas) { return }

    try {
        $mainGrid = $AtajosFullPanel.Parent
        if ($null -eq $mainGrid -or $mainGrid -isnot [System.Windows.Controls.Grid]) { return }

        $global:Window.UpdateLayout()
        $defs = $mainGrid.RowDefinitions
        $heights = New-Object System.Collections.Generic.List[double]

        for ($i = 0; $i -lt $defs.Count; $i++) {
            $h = [double]$defs[$i].ActualHeight
            if ($h -lt 1) {
                $h = [double]$defs[$i].Height.Value
            }
            $heights.Add($h)
        }

        for ($i = 0; $i -lt $defs.Count; $i++) {
             $defs[$i].Height = [System.Windows.GridLength]::new([double]$heights[$i])
        }

        $global:MainLayoutRowHeights = $heights.ToArray()
        $global:MainLayoutRowsFijadas = $true
    } catch { }
}

$BtnAtajo.Add_Click({
    if (-not $ChkCompartida.IsChecked) {
        if ($null -eq $global:RutaOriginalRespaldo) {
            $global:RutaOriginalRespaldo = $TxtRuta.Text
        }

        if ($global:RutaOriginalRespaldo -eq "Seleccionar carpeta para monitorizar." -or [string]::IsNullOrWhiteSpace($global:RutaOriginalRespaldo)) {
            $global:msgErrorRuta = "Seleccion$([char]0x00E1) una carpeta y compartila antes de entrar ac$([char]0x00E1)"
        } else {
            $global:msgErrorRuta = "Compart$([char]0x00ED) la carpeta antes de entrar ac$([char]0x00E1)"
        }

        if ($global:TimerRutaError) { $global:TimerRutaError.Stop() }
        if ($global:timerSwapRuta) { $global:timerSwapRuta.Stop() }
        if ($global:timerRestoreRuta) { $global:timerRestoreRuta.Stop() }

        $animOut = New-Object System.Windows.Media.Animation.DoubleAnimation
        $animOut.From = 1.0; $animOut.To = 0.0
        $animOut.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
        $TxtRuta.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animOut)

        $global:timerSwapRuta = New-Object System.Windows.Threading.DispatcherTimer
        $global:timerSwapRuta.Interval = [TimeSpan]::FromMilliseconds(300)
        $global:timerSwapRuta.Add_Tick({
            $global:timerSwapRuta.Stop()
            $TxtRuta.Text = $global:msgErrorRuta
            
            $animIn = New-Object System.Windows.Media.Animation.DoubleAnimation
            $animIn.From = 0.0; $animIn.To = 1.0
            $animIn.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
            $TxtRuta.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animIn)
        })
        $global:timerSwapRuta.Start()

        $global:TimerRutaError = New-Object System.Windows.Threading.DispatcherTimer
        $global:TimerRutaError.Add_Tick({
            $global:TimerRutaError.Stop()
            if ($TxtRuta.Text -eq $global:msgErrorRuta) {
                $animOut2 = New-Object System.Windows.Media.Animation.DoubleAnimation
                $animOut2.From = 1.0; $animOut2.To = 0.0
                $animOut2.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
                $TxtRuta.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animOut2)
                
                $global:timerRestoreRuta = New-Object System.Windows.Threading.DispatcherTimer
                $global:timerRestoreRuta.Interval = [TimeSpan]::FromMilliseconds(300)
                $global:timerRestoreRuta.Add_Tick({
                    $global:timerRestoreRuta.Stop()
                    $TxtRuta.Text = $global:RutaOriginalRespaldo
                    $global:RutaOriginalRespaldo = $null
                    
                    $animIn2 = New-Object System.Windows.Media.Animation.DoubleAnimation
                    $animIn2.From = 0.0; $animIn2.To = 1.0
                    $animIn2.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
                    $TxtRuta.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animIn2)
                })
                $global:timerRestoreRuta.Start()
            }
        })
        $global:TimerRutaError.Interval = [TimeSpan]::FromSeconds(2.6)
        $global:TimerRutaError.Start()

        return
    }

    Fijar-LayoutPrincipal

    # Pre-posicionar el botón Volver y los íconos laterales ANTES de empezar la transición (con Opacity 0)
    $AtajosFullPanel.Opacity = 0
    $AtajosFullPanel.Visibility = "Visible"
    Alinear-VolverAtajos
    Posicionar-AppsLaterales

    Animar-HeaderMac -Mostrar $false
    Transicion-Paneles -OcultarBody $BodyPrincipal -OcultarBotones $BotonesPrincipal -MostrarBody $AtajosFullPanel -MostrarBotones $AtajosFullPanel -Direccion 1
})

$AtajosFullPanel.Add_SizeChanged({
    Posicionar-AppsLaterales
    Alinear-VolverAtajos
})

$BtnVolverAtajos.Add_Click({
    if ($global:AnimacionEnCurso) {
        $global:InterrumpirAnimacion = $true
        $global:VolverAlMenuPendiente = $true
