})

$BtnInstalar.Add_Click({
    if (-not $PSCommandPath -and [string]::IsNullOrWhiteSpace($global:CodigoEnMemoria)) {
        return
    }

    [System.Windows.Input.Mouse]::OverrideCursor = [System.Windows.Input.Cursors]::Wait
    $BtnInstalar.Dispatcher.Invoke([Action]{}, 'Render')

    try {
        if (-not (Test-Path $appDataFolder)) { New-Item -ItemType Directory -Path $appDataFolder | Out-Null }
        
        $utf8ConBom = New-Object System.Text.UTF8Encoding($true)

        if ($PSCommandPath) {
            $rawFile = [System.IO.File]::ReadAllText($PSCommandPath, [System.Text.Encoding]::UTF8).TrimStart([char]0xFEFF)
            [System.IO.File]::WriteAllText("$appDataFolder\AirDrop.ps1", $rawFile, $utf8ConBom)
        } else {
            $codigoLimpio = $global:CodigoEnMemoria.TrimStart([char]0xFEFF)
            if ($codigoLimpio -match [char]0x00C3) {
                $bytes1252 = [System.Text.Encoding]::GetEncoding(1252).GetBytes($codigoLimpio)
                $codigoLimpio = [System.Text.Encoding]::UTF8.GetString($bytes1252).TrimStart([char]0xFEFF)
            }
            [System.IO.File]::WriteAllText("$appDataFolder\AirDrop.ps1", $codigoLimpio, $utf8ConBom)
        }

        if (-not [string]::IsNullOrWhiteSpace($imageBase64)) {
            $cleanImg = $imageBase64 -replace "^data:.*;base64,", ""
            $pngBytes = [Convert]::FromBase64String($cleanImg)
            [System.IO.File]::WriteAllBytes($imgDest, $pngBytes)
            
            try {
                $pngSize = $pngBytes.Length
                $icoHeader = [byte[]]@(0, 0, 1, 0, 1, 0)
                $icoDir = [byte[]]@(0, 0, 0, 0, 1, 0, 32, 0)
                $icoDir += [BitConverter]::GetBytes([int]$pngSize)
                $icoDir += [BitConverter]::GetBytes([int]22)
                $icoFileBytes = $icoHeader + $icoDir + $pngBytes
                [System.IO.File]::WriteAllBytes($icoDest, $icoFileBytes)
            } catch { }
        }
        
        if (-not [string]::IsNullOrWhiteSpace($audioBase64)) {
            $cleanAudio = $audioBase64 -replace "^data:.*;base64,", ""
            $bytesAudio = [Convert]::FromBase64String($cleanAudio)
            [System.IO.File]::WriteAllBytes($audioDest, $bytesAudio)
        }

$vbsMonitorContent = @'
Set WshShell = CreateObject("WScript.Shell")
WshShell.Run "powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File """ & CreateObject("WScript.Shell").ExpandEnvironmentStrings("%APPDATA%") & "\AirDrop\AirDrop.ps1"" -MonitorBackground", 0, False
'@
        Set-Content -Path $vbsMonitorPath -Value $vbsMonitorContent -Encoding Ascii

        $vbsGuiContent = @'
Set WshShell = CreateObject("WScript.Shell")
WshShell.Run "powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File """ & CreateObject("WScript.Shell").ExpandEnvironmentStrings("%APPDATA%") & "\AirDrop\AirDrop.ps1""", 0, False
'@
        Set-Content -Path $vbsGuiPath -Value $vbsGuiContent -Encoding Ascii

        $regPath = "HKCU:\Software\Classes\AppUserModelId\AirDrop.App"
        if (-not (Test-Path $regPath)) { New-Item -Path $regPath -Force | Out-Null }
        Set-ItemProperty -Path $regPath -Name "DisplayName" -Value "AirDrop"
        if (Test-Path $imgDest) { Set-ItemProperty -Path $regPath -Name "IconUri" -Value $imgDest }

        try {
            $wshShell = New-Object -ComObject WScript.Shell
            $shortcut = $wshShell.CreateShortcut($startMenuPath)
            $shortcut.TargetPath = "wscript.exe"
            $shortcut.Arguments = "`"$vbsGuiPath`""
            $shortcut.WorkingDirectory = $appDataFolder
            if (Test-Path $icoDest) { $shortcut.IconLocation = "$icoDest, 0" }
            $shortcut.Save()
        } catch { }

        $currentUser = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
        $userSid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
        
        $xmlContent = @"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo>
    <Author>$currentUser</Author>
    <URI>\AirDrop</URI>
  </RegistrationInfo>
  <Triggers>
    <LogonTrigger>
      <Enabled>true</Enabled>
    </LogonTrigger>
  </Triggers>
  <Principals>
    <Principal id="Author">
      <UserId>$userSid</UserId>
      <LogonType>InteractiveToken</LogonType>
      <RunLevel>LeastPrivilege</RunLevel>
    </Principal>
  </Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>true</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>false</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
    <IdleSettings>
      <StopOnIdleEnd>true</StopOnIdleEnd>
      <RestartOnIdle>false</RestartOnIdle>
    </IdleSettings>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled>
    <Hidden>true</Hidden>
    <RunOnlyIfIdle>false</RunOnlyIfIdle>
    <WakeToRun>false</WakeToRun>
    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>
    <Priority>7</Priority>
  </Settings>
  <Actions Context="Author">
    <Exec>
      <Command>wscript.exe</Command>
      <Arguments>&quot;$vbsMonitorPath&quot;</Arguments>
    </Exec>
  </Actions>
</Task>
"@
        $xmlB64 = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($xmlContent))

        $adminCode = @"
            try {
                `$xmlBytes = [Convert]::FromBase64String('$xmlB64')
                `$xmlDecoded = [System.Text.Encoding]::UTF8.GetString(`$xmlBytes)
                Register-ScheduledTask -TaskName 'AirDrop' -Xml `$xmlDecoded -Force -ErrorAction Stop | Out-Null
            } catch { exit 1 }
"@
        $exitCode = Invoke-AdminCommand -ScriptCode $adminCode -Wait $true
        if ($exitCode -ne 0) { throw "Cancelado" }

        [System.Windows.Input.Mouse]::OverrideCursor = $null
        
        Start-Process wscript.exe -ArgumentList "`"$vbsMonitorPath`""
        Start-Process wscript.exe -ArgumentList "`"$vbsGuiPath`""
        
        $global:SalirSinVentana = $true
        if ($global:Window.IsVisible) { $global:Window.Close() }
        return

    } catch {
        [System.Windows.Input.Mouse]::OverrideCursor = $null
    }
})

if (($AutoInstall -or (-not $PSCommandPath)) -and (-not $isInstalled)) {
    try { [Win32]::SystemParametersInfo(0x0057, 0, [IntPtr]::Zero, 0) | Out-Null } catch {}
    $BtnInstalar.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
    try { [Win32]::SystemParametersInfo(0x0057, 0, [IntPtr]::Zero, 0) | Out-Null } catch {}
    $global:SalirSinVentana = $true
}

$BtnDesinstalar.Add_Click({
    Animar-HeaderMac -Mostrar $true
    Transicion-Paneles -OcultarBody $AyudaFullPanel -OcultarBotones $AyudaFullPanel -MostrarBody $BodyDesinstalar -MostrarBotones $BotonesDesinstalar -Direccion 1
})

$BtnCancelarDesinstalar.Add_Click({
    Animar-HeaderMac -Mostrar $false
    Transicion-Paneles -OcultarBody $BodyDesinstalar -OcultarBotones $BotonesDesinstalar -MostrarBody $AyudaFullPanel -MostrarBotones $AyudaFullPanel -Direccion -1
})

$BtnConfirmarDesinstalar.Add_Click({
    [System.Windows.Input.Mouse]::OverrideCursor = [System.Windows.Input.Cursors]::Wait
    $BtnConfirmarDesinstalar.Dispatcher.Invoke([Action]{}, 'Render')

    $cfg = Get-AppConfig
    $folderPath = if ($cfg.CarpetaActiva) { $cfg.CarpetaActiva } else { $cfg.Carpeta }
    $userName = $cfg.Usuario

    $adminCode = @"
        try {
            if ('$folderPath' -ne '') {
                `$share = Get-SmbShare -ErrorAction SilentlyContinue | Where-Object Path -eq '$folderPath'
                if (`$share) { Remove-SmbShare -Name `$share.Name -Force -ErrorAction SilentlyContinue }
            }

            if ('$userName' -ne '') {
                Remove-LocalUser -Name '$userName' -ErrorAction SilentlyContinue
            }

            Unregister-ScheduledTask -TaskName 'AirDrop' -Confirm:`$false -ErrorAction SilentlyContinue
            
            Remove-Item -Path 'HKCU:\Software\Classes\AppUserModelId\AirDrop.App' -Recurse -Force -ErrorAction SilentlyContinue
            
            `$MonitorProcs = Get-CimInstance Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" | Where-Object { `$_.CommandLine -match '-MonitorBackground' }

            if (`$MonitorProcs) { `$MonitorProcs | ForEach-Object { Stop-Process `$_.ProcessId -Force -ErrorAction SilentlyContinue } }
        } catch { exit 1 }
"@
    
    $exitCode = Invoke-AdminCommand -ScriptCode $adminCode -Wait $true
    [System.Windows.Input.Mouse]::OverrideCursor = $null

    if ($exitCode -eq 0) {
        if (Test-Path $startMenuPath) { Remove-Item $startMenuPath -Force -ErrorAction SilentlyContinue }
        
        $cmdArgs = "/c ping 127.0.0.1 -n 4 > nul & cd /d %TEMP% & rmdir /s /q `"$appDataFolder`""
        Start-Process cmd.exe -ArgumentList $cmdArgs -WindowStyle Hidden -WorkingDirectory "C:\"
        
        $global:Window.FindName("BordePrincipal").IsHitTestVisible = $false
        $global:Window.FindResource("AnimacionCerrar").Begin($global:Window, $true)
        
        Wait-Wpf -Milliseconds 150
        $global:Window.Close()
    } else {
        Animar-HeaderMac -Mostrar $false
        Transicion-Paneles -OcultarBody $BodyDesinstalar -OcultarBotones $BotonesDesinstalar -MostrarBody $AyudaFullPanel -MostrarBotones $AyudaFullPanel -Direccion -1
    }
})

function Restaurar-FocoVentana {
    try {
        $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper($global:Window)).Handle
        $global:Window.Topmost = $true
        if ($hwnd -ne [IntPtr]::Zero) { [Win32]::SetForegroundWindow($hwnd) | Out-Null }
        $global:Window.Activate() | Out-Null
        $global:Window.Topmost = $false
        $global:Window.Focus() | Out-Null
    } catch {}
}

$ChkWindows.Add_PreviewMouseLeftButtonDown({
    param($sender, $e)
    $e.Handled = $true
    $ChkWindows.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
})

$ChkWindows.Add_Click({
    if ($global:IgnorarClickWin) { return }

    $task = Get-ScheduledTask -TaskName "AirDrop" -ErrorAction SilentlyContinue
    if (-not $task) {
        $global:IgnorarClickWin = $true
        $ChkWindows.IsChecked = $false
        $global:IgnorarClickWin = $false
        return
    }

    $nuevoEstado = -not [bool]$ChkWindows.IsChecked

    [System.Windows.Input.Mouse]::OverrideCursor = [System.Windows.Input.Cursors]::Wait
    $ChkWindows.Dispatcher.Invoke([Action]{}, 'Render')
    $global:EjecutandoAdmin = $true

    try {
        if ($nuevoEstado) {
            $adminCode = "try { Enable-ScheduledTask -TaskName 'AirDrop' } catch { exit 1 }"
        } else {
            $adminCode = "try { Disable-ScheduledTask -TaskName 'AirDrop' } catch { exit 1 }"
        }
        $exitCode = Invoke-AdminCommand -ScriptCode $adminCode -Wait $true
    } finally {
        [System.Windows.Input.Mouse]::OverrideCursor = $null
        $global:EjecutandoAdmin = $false
    }

    Restaurar-FocoVentana

    if ($exitCode -eq 0) {
        Wait-Wpf -Milliseconds 300
        Restaurar-FocoVentana
        $global:IgnorarClickWin = $true
        $ChkWindows.IsChecked = $nuevoEstado
        $global:IgnorarClickWin = $false
    }
})

$BodyConfirmarRed    = $global:Window.FindName("BodyConfirmarRed")
$BotonesConfirmarRed = $global:Window.FindName("BotonesConfirmarRed")
$BtnCancelarRed      = $global:Window.FindName("BtnCancelarRed")
$BtnConfirmarRed     = $global:Window.FindName("BtnConfirmarRed")

$ChkCompartida.Add_PreviewMouseLeftButtonDown({
    param($sender, $e)
    $e.Handled = $true
    $ChkCompartida.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
})

$ChkCompartida.Add_Click({
    if ($global:IgnorarClick) { return }

    $ruta = $TxtRuta.Text
    $esMensajeError = ($null -ne $global:msgErrorRuta -and $ruta -eq $global:msgErrorRuta)

    if (-not (Test-Path -LiteralPath $ruta) -or $ruta -eq "Seleccionar carpeta para monitorizar." -or $esMensajeError) {
        if ($null -eq $global:RutaOriginalRespaldo) {
            $global:RutaOriginalRespaldo = $TxtRuta.Text
        }

        $global:msgErrorRuta = "Seleccion$([char]0x00E1) una carpeta primero usando el bot$([char]0x00F3)n '...'"

        if ($global:TimerRutaError) { $global:TimerRutaError.Stop() }
        if ($global:timerSwapRuta) { $global:timerSwapRuta.Stop() }
        if ($global:timerRestoreRuta) { $global:timerRestoreRuta.Stop() }

        $animOut = New-Object System.Windows.Media.Animation.DoubleAnimation
        $animOut.From = 1.0; $animOut.To = 0.0
        $animOut.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
        $TxtRuta.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animOut)

        $global:timerSwapRuta = New-Object System.Windows.Threading.DispatcherTimer
        $global:timerSwapRuta.Interval = [TimeSpan]::FromMilliseconds(300)
        $global:timerSwapRuta.Add_Tick({
            $global:timerSwapRuta.Stop()
            $TxtRuta.Text = $global:msgErrorRuta
            
            $animIn = New-Object System.Windows.Media.Animation.DoubleAnimation
            $animIn.From = 0.0; $animIn.To = 1.0
            $animIn.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
            $TxtRuta.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animIn)
        })
        $global:timerSwapRuta.Start()

        $global:TimerRutaError = New-Object System.Windows.Threading.DispatcherTimer
        $global:TimerRutaError.Add_Tick({
            $global:TimerRutaError.Stop()
            if ($TxtRuta.Text -eq $global:msgErrorRuta) {
                $animOut2 = New-Object System.Windows.Media.Animation.DoubleAnimation
                $animOut2.From = 1.0; $animOut2.To = 0.0
                $animOut2.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
                $TxtRuta.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animOut2)
                
                $global:timerRestoreRuta = New-Object System.Windows.Threading.DispatcherTimer
                $global:timerRestoreRuta.Interval = [TimeSpan]::FromMilliseconds(300)
                $global:timerRestoreRuta.Add_Tick({
                    $global:timerRestoreRuta.Stop()
                    $TxtRuta.Text = $global:RutaOriginalRespaldo
                    $global:RutaOriginalRespaldo = $null
                    
                    $animIn2 = New-Object System.Windows.Media.Animation.DoubleAnimation
                    $animIn2.From = 0.0; $animIn2.To = 1.0
                    $animIn2.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
                    $TxtRuta.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animIn2)
                })
                $global:timerRestoreRuta.Start()
            }
        })
        $global:TimerRutaError.Interval = [TimeSpan]::FromSeconds(2.6)
        $global:TimerRutaError.Start()

        return
    }

    if (-not $ChkCompartida.IsChecked) {
        Transicion-Paneles -OcultarBody $BodyPrincipal -OcultarBotones $BotonesPrincipal -MostrarBody $BodyConfirmarRed -MostrarBotones $BotonesConfirmarRed -Direccion 1
        return
    }

    [System.Windows.Input.Mouse]::OverrideCursor = [System.Windows.Input.Cursors]::Wait
    $ChkCompartida.Dispatcher.Invoke([Action]{}, 'Render')
    $global:EjecutandoAdmin = $true

    try {
        $cleanRuta = $ruta.TrimEnd('\')
        $sharesLocales = Get-SmbShare -ErrorAction SilentlyContinue | Where-Object { $_.Path.TrimEnd('\') -eq $cleanRuta }
        if (-not $sharesLocales) {
            $cfg = Get-AppConfig
            $cfg.CarpetaActiva = ""
            Save-AppConfig $cfg
            $global:IgnorarClick = $true
            $ChkCompartida.IsChecked = $false
            $global:IgnorarClick = $false
            return
        }

        $adminCode = "try { " +
            "`$path = '$cleanRuta'; " +
            "`$shares = Get-SmbShare -ErrorAction SilentlyContinue | Where-Object { `$_.Path.TrimEnd('\') -eq `$path }; " +
            "if (`$shares) { `$shares | ForEach-Object { Remove-SmbShare -Name `$_.Name -Force -ErrorAction SilentlyContinue } }; " +
        "} catch { exit 1 }"
        
        $exitCode = Invoke-AdminCommand -ScriptCode $adminCode -Wait $true
    } finally {
        [System.Windows.Input.Mouse]::OverrideCursor = $null
        $global:EjecutandoAdmin = $false
    }

    Restaurar-FocoVentana

    if ($exitCode -eq 0) {
        $cfg = Get-AppConfig
        $cfg.CarpetaActiva = ""
        Save-AppConfig $cfg

        Wait-Wpf -Milliseconds 300
        Restaurar-FocoVentana

        $global:IgnorarClick = $true
        $ChkCompartida.IsChecked = $false
        $global:IgnorarClick = $false
    }
})

$BtnCancelarRed.Add_Click({
    Transicion-Paneles -OcultarBody $BodyConfirmarRed -OcultarBotones $BotonesConfirmarRed -MostrarBody $BodyPrincipal -MostrarBotones $BotonesPrincipal -Direccion -1
})

$BtnConfirmarRed.Add_Click({
    Transicion-Paneles -OcultarBody $BodyConfirmarRed -OcultarBotones $BotonesConfirmarRed -MostrarBody $BodyPrincipal -MostrarBotones $BotonesPrincipal -Direccion -1

    $ruta = $TxtRuta.Text
    [System.Windows.Input.Mouse]::OverrideCursor = [System.Windows.Input.Cursors]::Wait
    $BtnConfirmarRed.Dispatcher.Invoke([Action]{}, 'Render')
    $global:EjecutandoAdmin = $true

    try {
        $adminCode = "try { " +
            "`$path = '$ruta'.TrimEnd('\'); " +
            "`$shareName = (Get-Item -LiteralPath `$path).Name; " +
            "`$existing = Get-SmbShare -Name `$shareName -ErrorAction SilentlyContinue; " +
            "if (`$existing) { Remove-SmbShare -Name `$shareName -Force -ErrorAction SilentlyContinue }; " +
            "`$everyoneSid = New-Object System.Security.Principal.SecurityIdentifier('S-1-1-0'); " +
            "`$everyone = `$everyoneSid.Translate([System.Security.Principal.NTAccount]).Value; " +
            "`$acl = Get-Acl -LiteralPath `$path; " +
            "`$rule = New-Object System.Security.AccessControl.FileSystemAccessRule(`$everyoneSid, 'Modify', 'ContainerInherit,ObjectInherit', 'None', 'Allow'); " +
            "`$acl.AddAccessRule(`$rule); " +
            "Set-Acl -LiteralPath `$path -AclObject `$acl -ErrorAction Stop; " +
            "New-SmbShare -Name `$shareName -Path `$path -FullAccess `$everyone -ErrorAction Stop | Out-Null; " +
            "Get-NetConnectionProfile -ErrorAction SilentlyContinue | Where-Object { `$_.NetworkCategory -ne 'Private' } | ForEach-Object { Set-NetConnectionProfile -InterfaceIndex `$_.InterfaceIndex -NetworkCategory Private -ErrorAction SilentlyContinue }; " +
            "netsh advfirewall firewall set rule group='@FirewallAPI.dll,-32752' new enable=Yes profile=private | Out-Null; " +
            "netsh advfirewall firewall set rule group='@FirewallAPI.dll,-28502' new enable=Yes profile=private | Out-Null; " +
            "netsh advfirewall firewall set rule group='@FirewallAPI.dll,-32752' new enable=No profile=public | Out-Null; " +
            "netsh advfirewall firewall set rule group='@FirewallAPI.dll,-28502' new enable=No profile=public | Out-Null; " +
            "Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Lsa' -Name 'everyoneincludesanonymous' -Value 0 -Force; " +
            "Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Services\LanmanServer\Parameters' -Name 'restrictnullsessaccess' -Value 1 -Force; " +
            "Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Lsa\MSV1_0' -Name 'NtlmMinClientSec' -Value 536870912 -Force; " +
            "Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Lsa\MSV1_0' -Name 'NtlmMinServerSec' -Value 536870912 -Force; " +
        "} catch { exit 1 }"
        
        $exitCode = Invoke-AdminCommand -ScriptCode $adminCode -Wait $true
    } finally {
        [System.Windows.Input.Mouse]::OverrideCursor = $null
        $global:EjecutandoAdmin = $false
    }

    Restaurar-FocoVentana

    if ($exitCode -eq 0) {
        $cfg = Get-AppConfig
        $cfg.CarpetaActiva = $ruta
        Save-AppConfig $cfg

        if (Test-Path $vbsMonitorPath) {
            $monRunning = Get-CimInstance Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" | Where-Object { $_.CommandLine -match '-MonitorBackground' }
            if (-not $monRunning) {
                Start-Process wscript.exe -ArgumentList "`"$vbsMonitorPath`""
            }
        }

        Wait-Wpf -Milliseconds 300
        Restaurar-FocoVentana

        $global:IgnorarClick = $true
        $ChkCompartida.IsChecked = $true
        $global:IgnorarClick = $false

        try { 
            $sbExito = $global:Window.FindResource('AnimacionExito')
            if ($sbExito) { $sbExito.Begin($global:Window, $true) }
        } catch {}
    }
})

$BtnExaminar.Add_Click({
    $dialog = New-Object System.Windows.Forms.OpenFileDialog
    $dialog.Title = "Seleccionar carpeta para monitorizar (Entr$([char]0x00E1) a la carpeta y dale a Abrir)"
    $dialog.ValidateNames = $false
    $dialog.CheckFileExists = $false
    $dialog.CheckPathExists = $true
    $dialog.FileName = "Seleccionar esta carpeta"
    
    if (Test-Path $TxtRuta.Text) { $dialog.InitialDirectory = $TxtRuta.Text }
    
    if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        $selectedPath = [System.IO.Path]::GetDirectoryName($dialog.FileName)
        
        $global:RutaOriginalRespaldo = $selectedPath
        
        $cfg = Get-AppConfig
        $oldPath = if ($cfg.CarpetaActiva) { $cfg.CarpetaActiva } else { $cfg.Carpeta }

        if ($oldPath -and (Test-Path $oldPath) -and ($oldPath -ne $selectedPath)) {
            $sharesViejos = Get-SmbShare -ErrorAction SilentlyContinue | Where-Object Path -eq $oldPath
            if ($sharesViejos) {
                $unshareCode = "try { `$path = '$oldPath'; `$shares = Get-SmbShare -ErrorAction SilentlyContinue | Where-Object Path -eq `$path; if (`$shares) { `$shares | ForEach-Object { Remove-SmbShare -Name `$_.Name -Force -ErrorAction SilentlyContinue } } } catch {}"
                Invoke-AdminCommand -ScriptCode $unshareCode -Wait $false | Out-Null
            }
        }

        $TxtRuta.Text = $selectedPath
        $cfg.Carpeta = $selectedPath
        
        if (Test-AirDropConditions -Path $selectedPath) {
            $cfg.CarpetaActiva = $selectedPath
            $ChkCompartida.IsChecked = $true
        } else {
            $cfg.CarpetaActiva = ""
            $ChkCompartida.IsChecked = $false
        }
        Save-AppConfig $cfg

        if (Test-Path $vbsMonitorPath) {
            $MonitorProcs = Get-CimInstance Win32_Process -Filter "Name='powershell.exe' OR Name='pwsh.exe'" | Where-Object { $_.CommandLine -match '-MonitorBackground' }
            if ($MonitorProcs) { $MonitorProcs | ForEach-Object { Stop-Process $_.ProcessId -Force -ErrorAction SilentlyContinue } }
            Start-Process wscript.exe -ArgumentList "`"$vbsMonitorPath`""
        }
    }
})

