$BtnContinuar.Add_Click({
    $BtnContinuar.Dispatcher.Invoke([Action]{}, 'Render')
    
    $user = $TxtUsuario.Text
    $pass = $TxtPassword.Text
    
    $esPlaceholderUsuario = ([string]::IsNullOrWhiteSpace($user) -or $user -eq "Escribir usuario..." -or $user -eq "No se admiten espacios")
    $esPlaceholderPassword = ([string]::IsNullOrWhiteSpace($pass) -or $pass -eq $global:PlaceholderPass)
    
    $errorEspacios = ($user -match '\s') -and (-not $esPlaceholderUsuario)
    
    if ($errorEspacios) {
        $global:UserConEspacios = $user
        
        $animOut = New-Object System.Windows.Media.Animation.DoubleAnimation
        $animOut.From = 1.0; $animOut.To = 0.0; $animOut.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
        $TxtUsuario.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animOut)
        
        if ($global:timerSwap) { $global:timerSwap.Stop() }
        $global:timerSwap = New-Object System.Windows.Threading.DispatcherTimer
        $global:timerSwap.Interval = [TimeSpan]::FromMilliseconds(300)
        $global:timerSwap.Add_Tick({
            $global:timerSwap.Stop()
            $TxtUsuario.Text = "No se admiten espacios"
            $TxtUsuario.Foreground = "#86868B"
            
            $animIn = New-Object System.Windows.Media.Animation.DoubleAnimation
            $animIn.From = 0.0; $animIn.To = 1.0; $animIn.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
            $TxtUsuario.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animIn)
        })
        $global:timerSwap.Start()

        if ($global:TimerEspacios) { $global:TimerEspacios.Stop() }
        $global:TimerEspacios = New-Object System.Windows.Threading.DispatcherTimer
        $global:TimerEspacios.Add_Tick({
            $global:TimerEspacios.Stop()
            
            if ($TxtUsuario.Text -eq "No se admiten espacios") {
                $animOut2 = New-Object System.Windows.Media.Animation.DoubleAnimation
                $animOut2.From = 1.0; $animOut2.To = 0.0; $animOut2.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
                $TxtUsuario.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animOut2)
                
                if ($global:timerRestore) { $global:timerRestore.Stop() }
                $global:timerRestore = New-Object System.Windows.Threading.DispatcherTimer
                $global:timerRestore.Interval = [TimeSpan]::FromMilliseconds(300)
                $global:timerRestore.Add_Tick({
                    $global:timerRestore.Stop()
                    $TxtUsuario.Text = $global:UserConEspacios
                    $TxtUsuario.Foreground = "#1D1D1F"
                    
                    $animIn2 = New-Object System.Windows.Media.Animation.DoubleAnimation
                    $animIn2.From = 0.0; $animIn2.To = 1.0; $animIn2.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))
                    $TxtUsuario.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animIn2)
                })
                $global:timerRestore.Start()
            }
        })
        $global:TimerEspacios.Interval = [TimeSpan]::FromSeconds(2.6) 
        $global:TimerEspacios.Start()
        
        return
    }

    if ($esPlaceholderUsuario -or $esPlaceholderPassword) {
        $animParpadeo = New-Object System.Windows.Media.Animation.ColorAnimation
        $animParpadeo.To = [System.Windows.Media.ColorConverter]::ConvertFromString("#D1D1D6")
        $animParpadeo.Duration = [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(150))
        $animParpadeo.AutoReverse = $true
        $animParpadeo.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::new(2)

        if ($esPlaceholderUsuario) {
            $bordeUsuario = $TxtUsuario.Parent
            $brushU = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Colors]::White)
            $bordeUsuario.Background = $brushU
            $brushU.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $animParpadeo)
        }
        
        if ($esPlaceholderPassword) {
            $bordePassword = $TxtPassword.Parent
            $brushP = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.Colors]::White)
            $bordePassword.Background = $brushP
            $brushP.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty, $animParpadeo)
        }
        return
    }

    [System.Windows.Input.Mouse]::OverrideCursor = [System.Windows.Input.Cursors]::Wait
    $BtnContinuar.Dispatcher.Invoke([Action]{}, 'Render')

    $adminCode = @"
        try {
            `$passSecure = ConvertTo-SecureString '$pass' -AsPlainText -Force
            if (Get-LocalUser -Name '$user' -ErrorAction SilentlyContinue) {
                try {
                    Set-LocalUser -Name '$user' -Password `$passSecure -ErrorAction Stop
                    Set-LocalUser -Name '$user' -PasswordNeverExpires `$true -ErrorAction SilentlyContinue
                    Enable-LocalUser -Name '$user' -ErrorAction SilentlyContinue
                } catch {
                    & net.exe user "$user" "$pass" /active:yes | Out-Null
                    & net.exe accounts /maxpwage:unlimited | Out-Null
                }
            } else {
                New-LocalUser -Name '$user' -Password `$passSecure -PasswordNeverExpires -ErrorAction Stop | Out-Null
            }
            
            `$grupo = (Get-LocalGroup | Where-Object SID -match 'S-1-5-32-545').Name
            if (`$grupo) {
                try { Add-LocalGroupMember -Group `$grupo -Member '$user' -ErrorAction Stop } catch {}
            }
            exit 0
        } catch { exit 1 }
"@
    
    try {
        $exitCode = Invoke-AdminCommand -ScriptCode $adminCode -Wait $true
        [System.Windows.Input.Mouse]::OverrideCursor = $null

        if ($exitCode -ne 0) { return }

        $cfg = Get-AppConfig
        $cfg.Usuario = $user
        $cfg.Contrasena = $pass
        $cfg.Creado = (Get-Date).ToString("yyyy-MM-dd HH:mm:ss")
        Save-AppConfig $cfg

        $BtnCredenciales.Content = "Ver credenciales"
        $BtnCredenciales.Style = $global:Window.FindResource("BotonMacSecundario")
        $BtnAtajo.Style = $global:Window.FindResource("BotonMacPrimario")
        Transicion-Paneles -OcultarBody $BodyCredenciales -OcultarBotones $BotonesCredenciales -MostrarBody $BodyPrincipal -MostrarBotones $BotonesPrincipal -Direccion -1
        
    } catch {
        [System.Windows.Input.Mouse]::OverrideCursor = $null
    }
})

# ==========================================================
# LOGICA DE APPS Y ANIMACIONES INTEGRADAS (COMPORTAMIENTO IOS)
# ==========================================================
$global:AnimacionEnCurso = $false
$global:AnimacionPausada = $false
$global:AppActual = $null
$global:StoryboardActual = $null
$global:StopwatchActual = $null
$global:TiempoCierreActual = 0
$global:PauseOverlays = @{}

function Inicializar-PauseOverlays {
    # ==========================================================
    # AJUSTE DE OPACIDAD (De 0.10 a 1.00 -> 0.85 = 85%)
    # ==========================================================
    $OpacidadIconos  = 0.85   # <-- Opacidad de los  conos Play y Pausa
    $OpacidadCirculo = 0.60   # <-- Opacidad del c rculo que destella al hacer clic

    $hexIconos  = "{0:X2}" -f [int]([Math]::Round([Math]::Min(1.0, [Math]::Max(0.0, $OpacidadIconos)) * 255))
    $hexCirculo = "{0:X2}" -f [int]([Math]::Round([Math]::Min(1.0, [Math]::Max(0.0, $OpacidadCirculo)) * 255))

    $apps = @(
        @{ Key = "Archivos"; BorderName = "Ar_RealBackground"; ContainerName = "Ar_AnimacionContainer"; IconName = "Ar_AppIconContainer" },
        @{ Key = "Atajos";   BorderName = "At_RealBackground"; ContainerName = "At_AnimacionContainer"; IconName = "At_AppIconContainer" },
        @{ Key = "Fotos";    BorderName = "Fo_RealBackground"; ContainerName = "Fo_AnimacionContainer"; IconName = "Fo_AppIconContainer" }
    )

    foreach ($app in $apps) {
        # 1. Evitar que el  cono central (cuando tiene Opacity=0) bloquee los clics en el medio
        $iconCont = $global:Window.FindName($app.IconName)
        if ($null -ne $iconCont) { $iconCont.IsHitTestVisible = $false }

        $realBg = $global:Window.FindName($app.BorderName)
        $animCont = $global:Window.FindName($app.ContainerName)
        if ($null -eq $realBg -or $null -eq $realBg.Child -or $null -eq $animCont) { continue }

        $animCont.Cursor = [System.Windows.Input.Cursors]::Hand

        # 2. ZStack estilo Apple Music iOS con opacidad configurable y sombra suave para fondos claros
        [xml]$overlayXaml = @"
        <Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
              xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
              HorizontalAlignment="Stretch" VerticalAlignment="Stretch"
              IsHitTestVisible="False" Panel.ZIndex="9999">
            
            <Grid Width="115" Height="115" HorizontalAlignment="Center" VerticalAlignment="Center">
                <!-- Sombra suave para que el blanco resalte incluso sobre fondos blancos -->
                <Grid.Effect>
                    <DropShadowEffect Color="Black" BlurRadius="14" ShadowDepth="0" Opacity="0.22"/>
                </Grid.Effect>

                <!-- Capa 1: C rculo que aparece y desaparece r pido al tocar -->
                <Ellipse x:Name="FlashCircle" Width="110" Height="110" Fill="#${hexCirculo}FFFFFF" Opacity="0" HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                    <Ellipse.RenderTransform>
                        <ScaleTransform x:Name="CircleScale" ScaleX="0.88" ScaleY="0.88"/>
                    </Ellipse.RenderTransform>
                </Ellipse>

                <!-- Capa 2:  cono Pause (pause.fill) -->
                <Grid x:Name="IconPause" Width="70" Height="70" Opacity="0" HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                    <Grid.RenderTransform>
                        <ScaleTransform x:Name="PauseScale" ScaleX="0" ScaleY="0"/>
                    </Grid.RenderTransform>
                    <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center">
                        <Rectangle Width="15" Height="48" RadiusX="4.5" RadiusY="4.5" Fill="#${hexIconos}FFFFFF" Margin="0,0,12,0"/>
                        <Rectangle Width="15" Height="48" RadiusX="4.5" RadiusY="4.5" Fill="#${hexIconos}FFFFFF"/>
                    </StackPanel>
                </Grid>

                <!-- Capa 3:  cono Play (play.fill) -->
                <Grid x:Name="IconPlay" Width="70" Height="70" Opacity="0" HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5">
                    <Grid.RenderTransform>
                        <ScaleTransform x:Name="PlayScale" ScaleX="0" ScaleY="0"/>
                    </Grid.RenderTransform>
                    <Canvas Width="52" Height="52" HorizontalAlignment="Center" VerticalAlignment="Center" Margin="7,0,0,0">
                        <Path Data="M 8,6 C 8,2.2 12.1,-0.1 15.4,1.9 L 45.4,20.4 C 48.5,22.3 48.5,26.7 45.4,28.6 L 15.4,47.1 C 12.1,49.1 8,46.8 8,43 Z" Fill="#${hexIconos}FFFFFF"/>
                    </Canvas>
                </Grid>
            </Grid>
        </Grid>
"@
        $ovReader = New-Object System.Xml.XmlNodeReader $overlayXaml
        $ovGrid = [Windows.Markup.XamlReader]::Load($ovReader)
        [void]$realBg.Child.Children.Add($ovGrid)

        $info = @{
            Root        = $ovGrid
            Circle      = $ovGrid.FindName("FlashCircle")
            CircleScale = $ovGrid.FindName("CircleScale")
            IconPause   = $ovGrid.FindName("IconPause")
            PauseScale  = $ovGrid.FindName("PauseScale")
            IconPlay    = $ovGrid.FindName("IconPlay")
            PlayScale   = $ovGrid.FindName("PlayScale")
        }
        $global:PauseOverlays[$app.Key] = $info

        $animCont.Add_PreviewMouseLeftButtonDown({
            param($sender, $e)
            if ($global:AnimacionEnCurso -and -not $global:InterrumpirAnimacion) {
                $e.Handled = $true
                Alternar-PausaAnimacion
            }
        })
    }
}

Inicializar-PauseOverlays

function Animar-SpringPlayPause($appKey, [string]$Estado) {
    if (-not $appKey -or -not $global:PauseOverlays.ContainsKey($appKey)) { return }
    $ov = $global:PauseOverlays[$appKey]

    if ($global:TimerCircleFlash) { $global:TimerCircleFlash.Stop() }
    if ($global:TimerAutoHidePlay) { $global:TimerAutoHidePlay.Stop() }

    # Ocultado r pido al cerrar la app
    if ($Estado -eq "Hide") {
        $durHide = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds(120))
        $animZero = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, $durHide)
        
        $ov.Circle.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animZero)
        $ov.IconPause.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animZero)
        $ov.IconPlay.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animZero)
        $ov.PauseScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $animZero)
        $ov.PauseScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $animZero)
        $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $animZero)
        $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $animZero)
        return
    }

    # 1. Destello r pido del c rculo de fondo (0 -> opacidad transl cida en 0.2s, y se apaga tras 0.2s)
    $easeOut = New-Object System.Windows.Media.Animation.QuadraticEase
    $easeOut.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
    $durCircle = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds(200))

    $animCircleIn = New-Object System.Windows.Media.Animation.DoubleAnimation(1.0, $durCircle)
    $animCircleIn.EasingFunction = $easeOut
    $animCircleScIn = New-Object System.Windows.Media.Animation.DoubleAnimation(0.88, 1.0, $durCircle)
    $animCircleScIn.EasingFunction = $easeOut

    $ov.Circle.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animCircleIn)
    $ov.CircleScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $animCircleScIn)
    $ov.CircleScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $animCircleScIn)

    $global:TimerCircleFlash = New-Object System.Windows.Threading.DispatcherTimer
    $global:TimerCircleFlash.Interval = [TimeSpan]::FromMilliseconds(200)
    $global:TimerCircleFlash.Add_Tick({
        $global:TimerCircleFlash.Stop()
        $durOut = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds(220))
        $animOut = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, $durOut)
        $ov.Circle.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animOut)
    }.GetNewClosure())
    $global:TimerCircleFlash.Start()

    # 2. Resorte (interpolatingSpring stiffness:170, damping:15) para el cruce entre Play y Pause
    $springIn = New-Object System.Windows.Media.Animation.BackEase
    $springIn.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut
    $springIn.Amplitude = 0.38

    $easeShrink = New-Object System.Windows.Media.Animation.CubicEase
    $easeShrink.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseOut

    $durSpring = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds(360))
    $durShrink = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds(200))

    if ($Estado -eq "Pause") {
        # Si es el primer clic (ambos estaban invisibles), Play arranca en 1 para verse encogerse hacia Pause
        if ($ov.IconPlay.Opacity -lt 0.05 -and $ov.IconPause.Opacity -lt 0.05) {
            $ov.IconPlay.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
            $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $null)
            $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $null)
            $ov.IconPlay.Opacity = 1.0
            $ov.PlayScale.ScaleX = 1.0
            $ov.PlayScale.ScaleY = 1.0
        }

        # Play se encoge (1 -> 0) y pierde opacidad (1 -> 0)
        $playScaleOut = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, $durShrink)
        $playScaleOut.EasingFunction = $easeShrink
        $playOpOut = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, $durShrink)

        # Pause crece con resorte (0 -> 1) y gana opacidad (0 -> 1)
        $pauseScaleIn = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, 1.0, $durSpring)
        $pauseScaleIn.EasingFunction = $springIn
        $pauseOpIn = New-Object System.Windows.Media.Animation.DoubleAnimation(1.0, $durShrink)

        $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $playScaleOut)
        $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $playScaleOut)
        $ov.IconPlay.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $playOpOut)

        $ov.PauseScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $pauseScaleIn)
        $ov.PauseScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $pauseScaleIn)
        $ov.IconPause.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $pauseOpIn)

    } elseif ($Estado -eq "Play") {
        # Pause se encoge (1 -> 0) y pierde opacidad (1 -> 0)
        $pauseScaleOut = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, $durShrink)
        $pauseScaleOut.EasingFunction = $easeShrink
        $pauseOpOut = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, $durShrink)

        # Play crece con resorte (0 -> 1) y gana opacidad (0 -> 1)
        $playScaleIn = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, 1.0, $durSpring)
        $playScaleIn.EasingFunction = $springIn
        $playOpIn = New-Object System.Windows.Media.Animation.DoubleAnimation(1.0, $durShrink)

        $ov.PauseScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $pauseScaleOut)
        $ov.PauseScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $pauseScaleOut)
        $ov.IconPause.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $pauseOpOut)

        $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $playScaleIn)
        $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $playScaleIn)
        $ov.IconPlay.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $playOpIn)

        # Desvanecer suavemente el  cono de Play tras completar el rebote para dejar limpia la animaci n
        $global:TimerAutoHidePlay = New-Object System.Windows.Threading.DispatcherTimer
        $global:TimerAutoHidePlay.Interval = [TimeSpan]::FromMilliseconds(420)
        $global:TimerAutoHidePlay.Add_Tick({
            $global:TimerAutoHidePlay.Stop()
            if (-not $global:AnimacionPausada) {
                $durFade = New-Object System.Windows.Duration([TimeSpan]::FromMilliseconds(200))
                $fadeOut = New-Object System.Windows.Media.Animation.DoubleAnimation(0.0, $durFade)
                $ov.IconPlay.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fadeOut)
            }
        }.GetNewClosure())
        $global:TimerAutoHidePlay.Start()
    }
}

function Resetear-BadgesPausa {
    if ($global:TimerCircleFlash) { $global:TimerCircleFlash.Stop() }
    if ($global:TimerAutoHidePlay) { $global:TimerAutoHidePlay.Stop() }

    foreach ($k in $global:PauseOverlays.Keys) {
        $ov = $global:PauseOverlays[$k]
        $ov.Circle.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
        $ov.CircleScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $null)
        $ov.CircleScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $null)
        $ov.IconPause.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
        $ov.PauseScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $null)
        $ov.PauseScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $null)
        $ov.IconPlay.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null)
        $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $null)
        $ov.PlayScale.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $null)

        $ov.Circle.Opacity = 0
        $ov.IconPause.Opacity = 0
        $ov.IconPlay.Opacity = 0
        $ov.PauseScale.ScaleX = 0; $ov.PauseScale.ScaleY = 0
        $ov.PlayScale.ScaleX = 0;  $ov.PlayScale.ScaleY = 0
    }
}

# ==========================================================
# CONFIGURACI N DE TIEMPOS DE PAUSA (EN MILISEGUNDOS)
# ==========================================================
$global:TiempoPausaCentroMs = 50   # <-- 50 = 0.05s de espera antes/despu s de abrir y cerrar (Apps y QR)

function Alternar-PausaAnimacion {
    if (-not $global:AnimacionEnCurso -or $global:InterrumpirAnimacion) { return }
    if ($null -eq $global:StoryboardActual -or $null -eq $global:StopwatchActual -or -not $global:AppActual) { return }

    # Tiempo real dentro del Storyboard
    $msSb = $global:OffsetInicialSb + $global:StopwatchActual.ElapsedMilliseconds
    if ($msSb -lt 1500 -or $msSb -ge ($global:FinInternoActual - 100)) { return }

    if (-not $global:AnimacionPausada) {
        $global:AnimacionPausada = $true
        $global:StopwatchActual.Stop()
        try { $global:StoryboardActual.Pause($global:Window) } catch { }
        Animar-SpringPlayPause -appKey $global:AppActual -Estado "Pause"
    } else {
        $global:AnimacionPausada = $false
        try { $global:StoryboardActual.Resume($global:Window) } catch { }
        $global:StopwatchActual.Start()
        Animar-SpringPlayPause -appKey $global:AppActual -Estado "Play"
    }
}

$global:FoBlurContainer = $global:Window.FindName("Fo_ContenidoParaDesenfoque")
$global:FoBlurEffect    = $global:Window.FindName("Fo_AppBlur")
if ($global:FoBlurContainer) { $global:FoBlurContainer.Effect = $null }

function Reproducir-Animacion($boton, $transForm, $targetY, $container, $storyboardName, $finInternoMs, $tiempoCierreMs) {
    if ($global:AnimacionEnCurso) { return }
    $global:AnimacionEnCurso = $true
    $global:AnimacionPausada = $false
    $global:InterrumpirAnimacion = $false
    $global:VolverAlMenuPendiente = $false
    $global:CerrarAppPendiente = $false

    if ($global:TimerLanzador) { $global:TimerLanzador.Stop() }

    Resetear-BadgesPausa

    $pausaMs = [int]([Math]::Max(0, $global:TiempoPausaCentroMs))
    $duracionViajeMs = 400
    $duracionCierreVentanaMs = 700

    $BtnVolverAtajos.Visibility = "Visible"
    $BtnVolverAtajos.IsEnabled = $true
    $BtnVolverAtajos.Opacity = 1.0

    $sb = $null
    try {
        [System.Windows.Controls.Panel]::SetZIndex($boton, 10)
        # Desactivamos los clics del bot n que viaja al centro para que NO bloquee el medio de la app
        $boton.IsHitTestVisible = $false
        $QrContainer.Cursor = [System.Windows.Input.Cursors]::Hand
        
        $qrEstaAca = $TransQr.X
        $qrEsChico = ($ScaleQr.ScaleX -lt 0.8 -and $qrEstaAca -le -200)
        
        if ($qrEsChico) {
            # MODO 1: Cambiando de una app a otra (viajan al centro en 400ms)
            Animar-FadeQrText 1 0 
            Animar-ScaleQr 0.3333 0 
            
            Animar-Icono $TransQr -275 (-$targetY) 0
            Animar-Icono $transForm 275 $targetY 0
            
            Wait-Wpf -Milliseconds $duracionViajeMs
        } else {
            # MODO 2: Apertura Inicial (QR se achica en 400ms -> espera $pausaMs -> viajan en 400ms)
            Animar-Icono $TransQr 0 0 0 
            Animar-FadeQrText 0 0
            
            Animar-ScaleQr 0.3333 0
            
            $delayViaje = $duracionViajeMs + $pausaMs
            Animar-Icono $TransQr -275 (-$targetY) $delayViaje
            Animar-Icono $transForm 275 $targetY $delayViaje
            
            Wait-Wpf -Milliseconds ($delayViaje + $duracionViajeMs)
            Animar-FadeQrText 1 0
        }

        $boton.Opacity = 0
        $container.Visibility = "Visible"

        # En los 3 Storyboards la apertura arranca a los 1000ms (0:0:1.0)
        $global:OffsetInicialSb = [Math]::Max(0, 1000 - $pausaMs)
        if ($pausaMs -gt 1000) {
            Wait-Wpf -Milliseconds ($pausaMs - 1000)
        }

        try {
            $sb = $global:Window.FindResource($storyboardName)
            if ($sb) { 
                $sb.Begin($global:Window, $true) 
                $sb.Seek($global:Window, [TimeSpan]::FromMilliseconds($global:OffsetInicialSb), [System.Windows.Media.Animation.TimeSeekOrigin]::BeginTime)
            }
        } catch { }

        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $global:StoryboardActual = $sb
        $global:StopwatchActual = $sw
        $global:FinInternoActual = $finInternoMs
        $global:TiempoCierreActual = $tiempoCierreMs
        
        # Tiempo en el que termina la  ltima animaci n interna + la pausa configurada antes de cerrarse
        $objetivoAntesDeCerrarSb = $finInternoMs + $pausaMs

        while (($global:OffsetInicialSb + $sw.ElapsedMilliseconds) -lt $objetivoAntesDeCerrarSb) {
            # Activar el BlurEffect de Fotos ÚNICAMENTE mientras el Centro de Control está visible (16.45s a 34.55s)
            $tActualSb = $global:OffsetInicialSb + $sw.ElapsedMilliseconds
            if ($global:AppActual -eq "Fotos" -and $global:FoBlurContainer) {
                if ($tActualSb -ge 16450 -and $tActualSb -le 34550) {
                    if ($null -eq $global:FoBlurContainer.Effect) { $global:FoBlurContainer.Effect = $global:FoBlurEffect }
                } else {
                    if ($null -ne $global:FoBlurContainer.Effect) { $global:FoBlurContainer.Effect = $null }
                }
            }

            Wait-Wpf -Milliseconds 30

            if ($global:InterrumpirAnimacion) {
                if ($global:AnimacionPausada) {
                    $global:AnimacionPausada = $false
                    if ($global:AppActual) {
                        Animar-SpringPlayPause -appKey $global:AppActual -Estado "Hide"
                    }
                    try { if ($sb) { $sb.Resume($global:Window) } } catch { }
                    $sw.Start()
                } elseif ($global:AppActual) {
                    Animar-SpringPlayPause -appKey $global:AppActual -Estado "Hide"
                }

                $tiempoActualSb = $global:OffsetInicialSb + $sw.ElapsedMilliseconds
                $minimoAbiertoSb = 1500 + $pausaMs
                if ($tiempoActualSb -lt $minimoAbiertoSb) { 
                    Wait-Wpf -Milliseconds ($minimoAbiertoSb - $tiempoActualSb) 
                }
                break
            }
        }

        # Asegurar que el BlurEffect quede desconectado al contraer o interrumpir la app
        if ($global:FoBlurContainer) { $global:FoBlurContainer.Effect = $null }

        # Ocultar cualquier  cono de Play/Pause antes de contraer la ventana
        if ($global:AppActual) {
            Animar-SpringPlayPause -appKey $global:AppActual -Estado "Hide"
        }

        # Saltar exactamente al inicio del cierre de la ventana y esperar los 700ms que dura la contracci n
        if ($sb) {
            try { $sb.Resume($global:Window) } catch { }
            $sb.Seek($global:Window, [TimeSpan]::FromMilliseconds($tiempoCierreMs), [System.Windows.Media.Animation.TimeSeekOrigin]::BeginTime)
        }
        Wait-Wpf -Milliseconds $duracionCierreVentanaMs

        # Pausa en el centro DESPU S de cerrarse (convertida en  cono) antes de volver a la columna izquierda
        if ($pausaMs -gt 0) {
            Wait-Wpf -Milliseconds $pausaMs
        }

        $sw.Stop()
        try { if ($sb) { $sb.Remove($global:Window) } } catch { }
    }
    finally {
        Resetear-BadgesPausa
        $global:AnimacionPausada = $false
        $global:StoryboardActual = $null
        $global:StopwatchActual = $null

        try { if ($sb) { $sb.Remove($global:Window) } } catch { }
        try { $container.Visibility = "Hidden" } catch { }
        try { $boton.Opacity = 1.0 } catch { }
        
        try { Animar-Icono $transForm 0 0 0 } catch { }
        
        # Restauramos el clic del bot n ahora que volvi  a la columna izquierda
        try { $boton.IsHitTestVisible = $true } catch { }
        try { [System.Windows.Controls.Panel]::SetZIndex($boton, 0) } catch { }
        try { $BtnVolverAtajos.Visibility = "Visible" } catch { }
        try { $BtnVolverAtajos.IsEnabled = $true } catch { }
        try { $BtnVolverAtajos.Opacity = 1.0 } catch { }
        
        $global:AnimacionEnCurso = $false
        $global:AppActual = $null

        $delayExpandirQr = $duracionViajeMs + $pausaMs

        if ($global:VolverAlMenuPendiente -or $global:CerrarAppPendiente) {
            $esMenu = $global:VolverAlMenuPendiente
            $global:VolverAlMenuPendiente = $false
            $global:CerrarAppPendiente = $false
            
            $QrContainer.Cursor = [System.Windows.Input.Cursors]::Arrow
            Animar-FadeQrText 0 0
            
            try { Animar-Icono $TransQr 0 0 0 } catch { }
            try { Animar-ScaleQr 1.0 $delayExpandirQr } catch { }
            
            if ($esMenu) {
                if ($global:TimerLanzador) { $global:TimerLanzador.Stop() }
                $global:TimerLanzador = New-Object System.Windows.Threading.DispatcherTimer
                $global:TimerLanzador.Interval = [TimeSpan]::FromMilliseconds($delayExpandirQr + 400)
                $tickLanzador = {
                    $global:TimerLanzador.Stop()
                    $BtnVolverAtajos.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
                }.GetNewClosure()
                $global:TimerLanzador.Add_Tick($tickLanzador)
                $global:TimerLanzador.Start()
            }
        }
        elseif ($global:SiguienteAppActiva) {
            $global:AppToLaunch = $global:SiguienteAppActiva
            $global:SiguienteAppActiva = $null
            
            if ($global:TimerLanzador) { $global:TimerLanzador.Stop() }
            $global:TimerLanzador = New-Object System.Windows.Threading.DispatcherTimer
            $global:TimerLanzador.Interval = [TimeSpan]::FromMilliseconds(30)
            $tickLanzador = {
                $global:TimerLanzador.Stop()
                $evt = New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)
                $botonDestino = $global:Window.FindName("BtnApp" + $global:AppToLaunch)
                if ($botonDestino) { $botonDestino.RaiseEvent($evt) }
            }.GetNewClosure()
            $global:TimerLanzador.Add_Tick($tickLanzador)
            $global:TimerLanzador.Start()
        } else {
            $QrContainer.Cursor = [System.Windows.Input.Cursors]::Arrow
            Animar-FadeQrText 0 0
            try { Animar-Icono $TransQr 0 0 0 } catch { }
            try { Animar-ScaleQr 1.0 $delayExpandirQr } catch { }
        }
    }
}

$BtnAppArchivos.Add_Click({ 
    if ($global:AnimacionEnCurso) {
        if ($global:AppActual -ne "Archivos") {
            $global:InterrumpirAnimacion = $true
            $global:SiguienteAppActiva = "Archivos"
        } else {
            Alternar-PausaAnimacion
        }
        return
    }
    $global:AppActual = "Archivos"

    $Ar_DisplayUsuario.Text = "Crear"
    $Ar_DisplayPassword.Text = "Credenciales"
    
    if (Test-Path $jsonPath) {
        try {
            $confActual = Get-Content $jsonPath -Raw | ConvertFrom-Json
            if (![string]::IsNullOrWhiteSpace($confActual.Usuario) -and ![string]::IsNullOrWhiteSpace($confActual.Contrasena)) {
                $Ar_DisplayUsuario.Text = $confActual.Usuario
                $Ar_DisplayPassword.Text = $confActual.Contrasena
            }
        } catch {}
    }

    Reproducir-Animacion $BtnAppArchivos $TransArchivos 95 $Ar_AnimacionContainer "Ar_MainAnimation" 15100 15900
})

$BtnAppAtajos.Add_Click({ 
    if ($global:AnimacionEnCurso) {
        if ($global:AppActual -ne "Atajos") {
            $global:InterrumpirAnimacion = $true
            $global:SiguienteAppActiva = "Atajos"
        } else {
            Alternar-PausaAnimacion
        }
        return
    }
    $global:AppActual = "Atajos"
    
    Reproducir-Animacion $BtnAppAtajos $TransAtajos 0 $At_AnimacionContainer "At_MainAnimation" 12200 12500
})

$BtnAppFotos.Add_Click({ 
    if ($global:AnimacionEnCurso) {
        if ($global:AppActual -ne "Fotos") {
            $global:InterrumpirAnimacion = $true
            $global:SiguienteAppActiva = "Fotos"
        } else {
            Alternar-PausaAnimacion
        }
        return
    }
    $global:AppActual = "Fotos"
    
    Reproducir-Animacion $BtnAppFotos $TransFotos -95 $Fo_AnimacionContainer "Fo_MainAnimation" 34600 35100
})

if (-not $global:AppIsRunning -and -not $global:SalirSinVentana) {
    $global:AppIsRunning = $true
    try {
        if ($null -eq [System.Windows.Application]::Current) {
            $app = New-Object System.Windows.Application
            $app.Run($global:Window) | Out-Null
        } else {
            $global:Window.ShowDialog() | Out-Null
        }
    } catch { }
}